
'use strict';
const flashcards=[{"id": "f1", "block": "bases", "q": "¿Qué define un incendio forestal?", "a": "Fuego sin control sobre terreno forestal que afecta a vegetación no destinada a arder. El tema excluye quemas autorizadas.", "page": 11}, {"id": "f2", "block": "bases", "q": "Recita las seis fases en orden.", "a": "Precalentamiento → pirólisis → ignición → combustión gaseosa → combustión sólida → enfriamiento. Tea, Noé, Humo, Oca, Ola, Oso.", "page": 5}, {"id": "f3", "block": "bases", "q": "¿Qué fases son previas al frente visible, cuál es el frente y cuáles quedan detrás?", "a": "1–3 antes; 4 (combustión gaseosa) frente; 5–6 después.", "page": 5}, {"id": "f4", "block": "bases", "q": "¿Qué produce la pirólisis?", "a": "Descomposición por calor: gases inflamables y residuo carbonoso. No es lo mismo que la ignición.", "page": 5}, {"id": "f5", "block": "bases", "q": "Relaciona 100, 200, 300 y 600 °C con las fases del material.", "a": "100: eliminación de humedad; 200: destilación de resinas/pirólisis; 300: combustión gaseosa; >600: combustión de carbón. Son referencias de fases distintas.", "page": 5}, {"id": "f6", "block": "bases", "q": "¿Qué diferencia convección, conducción y radiación?", "a": "Convección: fluido en movimiento. Conducción: calor por el sólido. Radiación: transmisión por ondas a través del espacio.", "page": 6}, {"id": "f7", "block": "bases", "q": "Ignitabilidad, sostenibilidad, combustibilidad y consumibilidad: ¿qué pregunta responde cada una?", "a": "¿Arranca? ¿Continúa? ¿A qué velocidad quema? ¿Cuánto se consume? En ese orden.", "page": 7}, {"id": "f8", "block": "anatomia", "q": "Nombra seis partes del incendio en el dibujo.", "a": "Frente/cabeza, cola, flancos, dedos/lenguas, entrantes/bolsas y focos secundarios.", "page": 7, "image": "anatomia"}, {"id": "f9", "block": "anatomia", "q": "¿Dedo o lengua y foco secundario son lo mismo?", "a": "No. El dedo es un saliente unido al incendio; el foco secundario es un fuego separado.", "page": 7}, {"id": "f10", "block": "anatomia", "q": "¿Qué indican un incendio alargado y uno que sigue valles?", "a": "Alargado: influencia de viento y/o pendiente. Sigue valles/barrancos: vientos de convección o topográficos.", "page": 8}, {"id": "f11", "block": "tipos", "q": "¿Qué quema un fuego de subsuelo y por qué puede pasar desapercibido?", "a": "Materia orgánica bajo superficie; poca intensidad, puede durar días/semanas y verse solo humo o ni eso.", "page": 8}, {"id": "f12", "block": "tipos", "q": "¿Cómo denomina CEIS el fuego que prende copas aisladas de forma intermitente?", "a": "Antorcheo. Vélez llama pasivo a ese comportamiento.", "page": 10}, {"id": "f13", "block": "tipos", "q": "¿Qué es copas pasivo en CEIS / Arkaute?", "a": "Copas y superficie avanzan acopladas; el de copas depende del de superficie. Vélez lo llama activo.", "page": 10}, {"id": "f14", "block": "tipos", "q": "¿Qué es copas activo en CEIS / Arkaute?", "a": "Avance de copas independiente del fuego de superficie. En Vélez: independiente, adelantado o doble.", "page": 10}, {"id": "f15", "block": "tipos", "q": "¿Qué diferencia copas dominadas por viento y por convección?", "a": "Viento: columna muy inclinada y saltos. Convección: gran columna de base ancha y altura, corrientes descendentes, frentes erráticos y remolinos.", "page": 34}, {"id": "f16", "block": "combustibles", "q": "¿Cómo se calcula la humedad del combustible?", "a": "[(Peso húmedo − peso seco) / peso seco] × 100. Puede superar el 100 % porque la referencia es el peso seco.", "page": 15}, {"id": "f17", "block": "combustibles", "q": "¿Qué distingue combustible total, disponible y restante?", "a": "Total: vivo + muerto. Disponible: lo que puede arder en el incendio. Restante: lo que previsiblemente no arderá.", "page": 12}, {"id": "f18", "block": "combustibles", "q": "¿Qué mide el tiempo de retardación?", "a": "Tiempo para reducir aproximadamente el 63 % de la diferencia entre humedad inicial y humedad de equilibrio.", "page": 13}, {"id": "f19", "block": "combustibles", "q": "¿Qué tiempos corresponden a <5, 5–25, 25–75 y >75 mm?", "a": "1, 10, 100 y 1.000 horas. Tea, Toro, Torre y Torre+Aro. En ese orden.", "page": 13}, {"id": "f20", "block": "combustibles", "q": "¿A qué grupos pertenecen los modelos 1–3, 4–7, 8–10 y 11–13?", "a": "Pastos; matorral; hojarasca bajo arbolado; restos de corta y operaciones selvícolas.", "page": 12}, {"id": "f21", "block": "combustibles", "q": "Modelos 1, 2 y 3: ¿cómo distingues los pastos?", "a": "1: fino seco bajo, leñosas <1/3. 2: fino seco bajo, leñosas 1/3–2/3. 3: grueso denso seco alto.", "page": 12}, {"id": "f22", "block": "combustibles", "q": "Modelos 4 y 5: ¿qué alturas cita el tema?", "a": "4: matorral muy denso >2 m. 5: matorral denso verde <1 m.", "page": 12}, {"id": "f23", "block": "combustibles", "q": "Modelos 8 y 9: ¿qué cambia?", "a": "Hojarasca compacta en 8 y menos compacta en 9; bosque denso sin matorral.", "page": 12}, {"id": "f24", "block": "combustibles", "q": "¿Qué caracterizan los modelos 10 y 13?", "a": "10: gran cantidad de leña y árboles caídos. 13: grandes acumulaciones de restos gruesos y pesados.", "page": 12}, {"id": "f25", "block": "combustibles", "q": "¿Qué porcentaje de humedad relaciona el tema con disponibilidad para arder?", "a": "Por debajo del 15–25 %. Es la referencia del material.", "page": 13}, {"id": "f26", "block": "magnitudes", "q": "¿Cuáles son los tres umbrales de velocidad de propagación en m/min?", "a": "0,5; 2; 10. Baja <0,5; moderada 0,5–2; alta 2–10; extrema >10.", "page": 14}, {"id": "f27", "block": "magnitudes", "q": "Convierte 0,5, 2 y 10 m/min a m/h.", "a": "30, 120 y 600 m/h, multiplicando por 60.", "page": 14}, {"id": "f28", "block": "magnitudes", "q": "¿Qué unidades distinguen calor por área e intensidad lineal?", "a": "Calor por área: kcal/m². Intensidad lineal: kcal/(m·s).", "page": 14}, {"id": "f29", "block": "magnitudes", "q": "¿Qué referencia da el párrafo para ataque directo manual?", "a": "1,20 m de longitud de llama. La tabla original se solapa: <1,2 y 1–2,5 m; esa diferencia está señalada.", "page": 14}, {"id": "f30", "block": "magnitudes", "q": "¿Qué especies son muy inflamables todo el año según el tema?", "a": "Brezo, tomillo, encina y eucalipto.", "page": 15}, {"id": "f31", "block": "magnitudes", "q": "¿Qué especies son muy inflamables solo en verano?", "a": "Tojo, escobones, pino pinaster, alcornoque, romero y zarza.", "page": 15}, {"id": "f32", "block": "magnitudes", "q": "¿Qué especies figuran como moderadas o poco inflamables?", "a": "Madroño, enebro y cedros.", "page": 15}, {"id": "f33", "block": "topografia", "q": "¿Cuáles son los tres factores topográficos?", "a": "Configuración/relieve, exposición de las laderas y pendiente.", "page": 15}, {"id": "f34", "block": "topografia", "q": "¿Cuál es el factor topográfico más importante y cómo influye?", "a": "Pendiente: aumenta precalentamiento por convección y radiación ladera arriba.", "page": 16}, {"id": "f35", "block": "topografia", "q": "¿Qué diferencia general hay entre solana y umbría?", "a": "La solana suele estar más caliente y seca por exposición solar. El tema destaca menos agua y, en general, menos combustible.", "page": 16}, {"id": "f36", "block": "topografia", "q": "¿Qué es el efecto chimenea?", "a": "Canalización ascendente de humo y calor por vaguadas, arroyos y gargantas, en sentido contrario al drenaje del agua.", "page": 33}, {"id": "f37", "block": "meteorologia", "q": "Recupera el triple efecto del viento.", "a": "Aporta oxígeno; inclina llamas y precalienta; transporta pavesas y genera focos secundarios.", "page": 18}, {"id": "f38", "block": "meteorologia", "q": "Cuando se indica la dirección del viento, ¿de dónde viene o hacia dónde va?", "a": "De dónde viene. El tema diferencia viento general/de gradiente y local.", "page": 18}, {"id": "f39", "block": "meteorologia", "q": "Describe el efecto Foehn en una cadena.", "a": "Ascenso de aire húmedo → enfriamiento/condensación/precipitación → descenso de aire más seco → calentamiento.", "page": 18, "image": "foehn"}, {"id": "f40", "block": "meteorologia", "q": "¿Qué es una inversión térmica?", "a": "Aire frío bajo una capa más caliente; en un valle puede limitar intercambio y el material describe reactivación al romperse.", "page": 17, "image": "inversion"}, {"id": "f41", "block": "meteorologia", "q": "¿Qué gradientes normal y seco cita el tema?", "a": "Normal ≈ −0,6 °C/100 m; seco −1 °C/100 m. La cifra de gradiente húmedo tiene un signo dudoso en el original.", "page": 20}, {"id": "f42", "block": "meteorologia", "q": "¿Cuándo predominan vientos locales ascendentes y descendentes?", "a": "Ascendentes de día; descendentes de noche.", "page": 20}, {"id": "f43", "block": "meteorologia", "q": "¿Qué es el punto de rocío?", "a": "Temperatura a la que se debe enfriar el aire para alcanzar la saturación.", "page": 20}, {"id": "f44", "block": "tecnicas", "q": "Relaciona desalimentación, sofocación y enfriamiento con el triángulo.", "a": "Eliminar combustible; separar comburente/oxígeno; retirar calor.", "page": 21}, {"id": "f45", "block": "tecnicas", "q": "¿Qué diferencia temporal hay entre cortafuego y línea de defensa?", "a": "Cortafuego: prevención antes de incendio. LD: durante el incendio.", "page": 21}, {"id": "f46", "block": "tecnicas", "q": "¿Qué efectos asigna el tema a retardantes y humectantes?", "a": "Retardantes: más viscosidad, menos escurrimiento. Humectantes: mayor penetración, expresada como menor diámetro de gotas.", "page": 22}, {"id": "f47", "block": "metodos", "q": "¿Qué distingue el método directo del indirecto?", "a": "Directo: sobre llamas/línea de fuego. Indirecto: líneas y combustible a distancia, cuando riesgo/intensidad aconsejan separarse.", "page": 26}, {"id": "f48", "block": "metodos", "q": "¿Quién ordena el contrafuego y qué condición personal destaca el tema?", "a": "Exclusivamente el Director de Extinción. No debe quedar nadie entre los dos fuegos.", "page": 26}, {"id": "f49", "block": "metodos", "q": "¿Qué es el ataque paralelo?", "a": "Avance próximo y paralelo al frente, apoyado en LC; prepara combustible y aprovecha barreras. El tema lo señala como el más peligroso.", "page": 27}, {"id": "f50", "block": "metodos", "q": "¿Qué es el método del área?", "a": "Caso especial del directo: reparto de recursos entre focos simultáneos, con liquidación que se completa después.", "page": 29}, {"id": "f51", "block": "metodos", "q": "¿Qué busca el ataque en pinza?", "a": "Limitar expansión por ambos flancos y reducir anchura de cabeza para facilitar ataque o indirecto.", "page": 31}, {"id": "f52", "block": "lineas", "q": "¿Qué es una línea de control?", "a": "Perímetro previsto en el plan para contener el incendio, integrado por barreras naturales, artificiales y líneas construidas.", "page": 30}, {"id": "f53", "block": "lineas", "q": "¿Hasta qué nivel se despeja una línea de defensa?", "a": "Hasta suelo mineral; inicio y terminación con puntos de anclaje seguros.", "page": 29}, {"id": "f54", "block": "lineas", "q": "¿Qué es la quema de ensanche?", "a": "Quema intencionada para ampliar zonas sin combustible y reforzar la línea.", "page": 30}, {"id": "f55", "block": "lineas", "q": "¿Qué es una línea negra?", "a": "Borde de lo quemado sin posibilidad de reproducirse el fuego.", "page": 52}, {"id": "f56", "block": "organizacion", "q": "Recita las tres partes del plan y su pregunta.", "a": "Estrategia: qué. Táctica: cómo. Horario: cuándo.", "page": 24}, {"id": "f57", "block": "organizacion", "q": "¿Quién asigna los recursos disponibles al combate?", "a": "CECOP: Centro de Coordinación Operativa.", "page": 23}, {"id": "f58", "block": "organizacion", "q": "¿Qué límites pone el tema a cuadrilla y brigada?", "a": "Cuadrilla: ≤5 operarios. Brigada: ≤5 cuadrillas. Cada una con responsable.", "page": 23}, {"id": "f59", "block": "organizacion", "q": "Recupera las cinco etapas del combate.", "a": "Reconocimiento/evaluación → ataque → control → liquidación → vigilancia activa y postincendio.", "page": 32}, {"id": "f60", "block": "organizacion", "q": "¿La liquidación solo comienza después del control?", "a": "No: puede comenzar en cualquier momento, por cola/flancos, para establecer líneas negras.", "page": 32}, {"id": "f61", "block": "peligro", "q": "Explica la regla del 30 y el sentido de cada desigualdad.", "a": "Dos o más factores: >30 °C; >30 km/h; >30 % de pendiente; <30 % de HR. Meru (30): tres suben, HR baja.", "page": 32}, {"id": "f62", "block": "peligro", "q": "¿Qué es continuidad de combustible en escalera?", "a": "Pastos → sotobosque → arbolado: favorece paso a copas.", "page": 32}, {"id": "f63", "block": "peligro", "q": "¿Qué diferencia pavesas de larga y corta distancia?", "a": "Larga: ligeras, cientos/miles de metros. Corta: más pesadas, decenas de metros; muchas = ducha de pavesas.", "page": 34}, {"id": "f64", "block": "peligro", "q": "¿Cómo se definen riesgo y gravedad anual en las notas?", "a": "Riesgo: incendios por 10.000 ha forestales. Gravedad: porcentaje de superficie forestal quemada en el año.", "page": 52}, {"id": "f65", "block": "herramientas", "q": "Identifica el Pulaski y su función.", "a": "Hacha–azada, filos perpendiculares. Retirar manto vegetal y trabajar raíces.", "page": 36, "image": "pulaski"}, {"id": "f66", "block": "herramientas", "q": "¿Cuántos dientes tiene el MacLeod y qué hay al otro lado?", "a": "Seis dientes gruesos; filo de corte opuesto. Oso (6) con seis uñas.", "page": 37, "image": "macleod"}, {"id": "f67", "block": "herramientas", "q": "¿Qué cuatro funciones reúne el Gorgui?", "a": "Azada, MacLeod, rastrillo y azada estrecha similar a Pulaski.", "page": 37, "image": "gorgui"}, {"id": "f68", "block": "herramientas", "q": "¿Qué mezcla y capacidad cita el tema para la antorcha de goteo?", "a": "2/3 gasóleo + 1/3 gasolina; aproximadamente 5 L. Noé (2), Tea (1), Humo (3) y Ola (5).", "page": 35}, {"id": "f69", "block": "herramientas", "q": "¿Qué límite de peso cargado cita para la mochila extintora?", "a": "No superar 20 kg. No confundir peso con capacidad en litros.", "page": 36}, {"id": "f70", "block": "herramientas", "q": "¿Por qué se dirige el golpe del batefuegos a lo quemado?", "a": "Para que pavesas y brasas se dispersen hacia una zona donde ya no sean peligrosas. Actúa por sofocación.", "page": 35}, {"id": "f71", "block": "maquinaria", "q": "¿Qué mezcla de combustible cita para motosierra y desbrozadora?", "a": "98 % gasolina + 2 % aceite. Bache (98) de gasolina, Noé (2) de aceite.", "page": 44}, {"id": "f72", "block": "maquinaria", "q": "¿Qué EPI específico del motoserrista destaca el tema?", "a": "Cubrepantalón, botas reforzadas, casco con gafas/pantalla, guantes y protección auditiva, además de ropa forestal.", "page": 40}, {"id": "f73", "block": "maquinaria", "q": "¿Por qué evitar cortar con el cuarto superior de la punta de la espada?", "a": "Para evitar rebotes; el material pide sujetar la motosierra con ambas manos.", "page": 43}, {"id": "f74", "block": "maquinaria", "q": "¿Para qué no está diseñado el vestuario forestal del material?", "a": "No protege específicamente de atrapamiento por fuego ni de riesgos de extinción estructural.", "page": 45}, {"id": "f75", "block": "maquinaria", "q": "¿Qué peso de tejido y rango de pendiente de maquinaria cita?", "a": "Tejido forestal: 200–300 g/m². Tractor: hasta 50–60 % de pendiente según las notas.", "page": 45}, {"id": "f76", "block": "seguridad", "q": "Desarrolla OACEL.", "a": "Observación; Atención (anclaje); Comunicación; ruta de Escape; Lugar seguro. Esta es la formulación del material.", "page": 52}, {"id": "f77", "block": "seguridad", "q": "¿Qué distancia entre combatientes citan las notas?", "a": "3 m. Humo (3): visualiza una columna entre cada pareja, como señal de la distancia.", "page": 52}, {"id": "f78", "block": "seguridad", "q": "¿Cómo se transportan herramientas manuales y cómo se llevan cerca del helicóptero?", "a": "En tierra: junto a la cabeza, paralelo al cuerpo y aguas abajo; nunca al hombro. Cerca del helicóptero: horizontal y según tripulación.", "page": 47}, {"id": "f79", "block": "seguridad", "q": "¿Qué dos zonas de aproximación al helicóptero descarta el tema?", "a": "Cola/parte trasera y punto alto de una ladera. Aproximación autorizada, visible por delante y sin correr.", "page": 47}, {"id": "f80", "block": "seguridad", "q": "¿Cómo se retira el personal del lugar previsto de descarga?", "a": "En ángulo recto a la trayectoria de la aeronave, según el protocolo del tema.", "page": 49}, {"id": "f81", "block": "seguridad", "q": "¿En qué categoría sitúa el material las cuadrillas helitransportadas?", "a": "Personal adicional especialista: sin función en operación de aeronave, con función en la actividad.", "page": 46}, {"id": "f82", "block": "seguridad", "q": "¿Cuáles son las cuatro partes principales del helibalde?", "a": "Balde, válvula, cables y cabeza de control; conectado al gancho de carga.", "page": 50, "image": "helibalde"}, {"id": "f83", "block": "seguridad", "q": "¿Qué capacidad de agua asigna la tabla a Bell 212, Bell 412 y Kamov?", "a": "1.500, 2.400 y 5.000 L, respectivamente. Son cifras de la tabla del temario.", "page": 51}, {"id": "f84", "block": "prediccion", "q": "¿Qué tres factores puntúa la alineación de Campbell?", "a": "Pendiente, viento y combustibilidad (frío/caliente). La orientación solar influye en el estado del combustible.", "page": 54}, {"id": "f85", "block": "prediccion", "q": "¿Qué significan 0/3, 1/3, 2/3 y 3/3?", "a": "Fuera, poca, media y plena alineación, respectivamente.", "page": 54}, {"id": "f86", "block": "prediccion", "q": "¿Qué añade cada generación del 1 al 6?", "a": "Continuidad → rapidez → copas/convección → IUF → simultaneidad → modificación de meteorología/tormentas de fuego.", "page": 53}, {"id": "f87", "block": "prediccion", "q": "¿Qué es IUF y a qué generación identifica en la tabla?", "a": "Interfaz urbano-forestal; rasgo central de la cuarta generación.", "page": 53}];
const quizdata=[{"block": "bases", "page": 5, "q": "¿Qué fase forma el frente visible de fuego?", "options": ["Pirólisis", "Combustión sólida", "Combustión gaseosa", "Enfriamiento"], "correct": 2, "explanation": "La fase 4 genera llamas; 1–3 van antes y 5–6 después del frente."}, {"block": "bases", "page": 7, "q": "¿Qué propiedad responde a «a qué velocidad quema»?", "options": ["Sostenibilidad", "Combustibilidad", "Ignitabilidad", "Consumibilidad"], "correct": 1, "explanation": "Combustibilidad: velocidad de quema. Sostenibilidad: mantener; ignitabilidad: iniciar; consumibilidad: consumirse."}, {"block": "bases", "page": 6, "q": "Una pavesa se eleva con aire caliente. ¿Qué mecanismo ilustra el tema?", "options": ["Convección", "Conducción", "Solo radiación", "Desalimentación"], "correct": 0, "explanation": "Convección: transporte por un fluido en movimiento. El tema usa las pavesas como ejemplo."}, {"block": "anatomia", "page": 7, "q": "Una llama separada del perímetro principal se denomina…", "options": ["Entrante", "Cola", "Dedo", "Foco secundario"], "correct": 3, "explanation": "Un dedo sigue unido al frente; un foco secundario es un incendio separado."}, {"block": "tipos", "page": 10, "q": "En CEIS, un frente de copas acoplado al de superficie es…", "options": ["Antorcheo", "Copas pasivo", "Copas activo independiente", "Subsuelo"], "correct": 1, "explanation": "CEIS/Arkaute usan pasivo para el avance acoplado. Vélez llama activo a ese mismo comportamiento."}, {"block": "tipos", "page": 9, "q": "En la clasificación atribuida a Vélez, árboles aislados que se inflaman esporádicamente son…", "options": ["Copas pasivo", "Copas activo", "Copas independiente", "Fuego de subsuelo"], "correct": 0, "explanation": "Vélez lo llama pasivo; CEIS y Arkaute usan antorcheo. La fuente de la pregunta es decisiva."}, {"block": "combustibles", "page": 15, "q": "Peso húmedo 180 g y seco 100 g. ¿Humedad según la fórmula del tema?", "options": ["44 %", "180 %", "80 %", "100 %"], "correct": 2, "explanation": "(180−100)/100 × 100 = 80 %. El denominador es el peso seco."}, {"block": "combustibles", "page": 13, "q": "Un combustible de 30 mm pertenece a la clase de…", "options": ["1 hora", "10 horas", "1.000 horas", "100 horas"], "correct": 3, "explanation": "30 mm está en 25–75 mm: medianos, 100 horas."}, {"block": "combustibles", "page": 12, "q": "¿Qué modelos son de matorral?", "options": ["1–3", "4–7", "8–10", "11–13"], "correct": 1, "explanation": "Las cuatro familias son pastos 1–3, matorral 4–7, hojarasca 8–10 y restos 11–13."}, {"block": "combustibles", "page": 13, "q": "El tiempo de retardación reduce aproximadamente…", "options": ["El 63 % de la diferencia inicial respecto al equilibrio", "El 100 % de toda el agua", "El 63 % del peso seco", "La temperatura en 63 °C"], "correct": 0, "explanation": "Se aplica a la diferencia de contenido de humedad, no al peso total ni a la temperatura."}, {"block": "magnitudes", "page": 14, "q": "Una cabeza avanza a 8 m/min. ¿Categoría?", "options": ["Baja", "Moderada", "Extrema", "Alta"], "correct": 3, "explanation": "Alta: 2–10 m/min. Equivale a 480 m/h."}, {"block": "magnitudes", "page": 14, "q": "¿Cuánto son 2 m/min?", "options": ["20 m/h", "200 m/h", "120 m/h", "600 m/h"], "correct": 2, "explanation": "Multiplica por 60 minutos: 2 × 60 = 120 m/h."}, {"block": "magnitudes", "page": 15, "q": "¿Qué grupo es muy inflamable todo el año según el tema?", "options": ["Madroño, enebro, cedros", "Brezo, tomillo, encina, eucalipto", "Solo pino pinaster y romero", "Tojo, escobones, alcornoque"], "correct": 1, "explanation": "El grupo de todo el año es brezo, tomillo, encina y eucalipto. Los otros aparecen en categorías diferentes."}, {"block": "topografia", "page": 16, "q": "¿Qué factor topográfico destaca como el más importante?", "options": ["Pendiente", "Solo altitud", "Hora del día", "Carga de combustible"], "correct": 0, "explanation": "La pendiente influye directamente en transmisión de calor por convección y radiación ladera arriba."}, {"block": "topografia", "page": 33, "q": "¿Cuál ilustra el efecto chimenea?", "options": ["Viento sobre un mar abierto", "Agua que desciende por un arroyo", "Conducción en una barra", "Humo y calor canalizados hacia arriba por una garganta"], "correct": 3, "explanation": "El relieve canaliza humo y calor en sentido contrario al drenaje de agua."}, {"block": "meteorologia", "page": 18, "q": "La dirección del viento indica…", "options": ["Hacia dónde van las llamas", "La pendiente dominante", "De dónde sopla", "Dónde está la cabeza"], "correct": 2, "explanation": "La dirección meteorológica indica procedencia, no destino."}, {"block": "meteorologia", "page": 18, "q": "¿Qué caracteriza el aire que desciende a sotavento en el Foehn?", "options": ["Más frío y húmedo necesariamente", "Más seco y calentándose", "Sin cambio térmico", "Siempre saturado"], "correct": 1, "explanation": "Tras ascenso y pérdida de humedad, el aire desciende seco y se calienta."}, {"block": "meteorologia", "page": 20, "q": "Según la regla del material, los vientos locales ascendentes se producen…", "options": ["De día", "Solo de noche", "Con independencia total del ciclo diario", "Solo con nieve"], "correct": 0, "explanation": "El tema resume ascendentes de día y descendentes de noche."}, {"block": "tecnicas", "page": 22, "q": "El batefuegos actúa principalmente por…", "options": ["Enfriamiento", "Evaporación", "Radiación", "Sofocación"], "correct": 3, "explanation": "Desplaza/separa aire en la base de la llama; el tema lo estudia como sofocación."}, {"block": "tecnicas", "page": 21, "q": "¿Qué diferencia temporal establece entre cortafuego y LD?", "options": ["Ambos siempre se crean después", "LD antes, cortafuego durante", "Cortafuego antes, LD durante", "No establece ninguna"], "correct": 2, "explanation": "Cortafuego: prevención. Línea de defensa: construcción durante el incendio."}, {"block": "metodos", "page": 26, "q": "¿Quién tiene responsabilidad exclusiva para ordenar contrafuego?", "options": ["Jefe de cuadrilla", "Director de Extinción", "Piloto", "Cualquier combatiente"], "correct": 1, "explanation": "El material atribuye la orden exclusivamente al DE y exige que no haya personas entre los fuegos."}, {"block": "metodos", "page": 29, "q": "El método del área se refiere a…", "options": ["Repartir medios entre focos simultáneos", "Medir hectáreas después", "Atacar siempre solo la cabeza", "Una clase de fuego subterráneo"], "correct": 0, "explanation": "Es un caso especial del directo ante simultaneidad, con liquidación que se completa después."}, {"block": "metodos", "page": 27, "q": "¿Qué ataque señala el tema como el más peligroso para el personal?", "options": ["Método del área", "Toda liquidación", "Ataque en pinza por definición", "Ataque paralelo"], "correct": 3, "explanation": "La página 27 y las tácticas de la 31 destacan esa peligrosidad del paralelo."}, {"block": "lineas", "page": 30, "q": "Una línea de control puede incluir…", "options": ["Solo una zanja", "Solo agua", "Barreras naturales, artificiales y fajas", "Únicamente cortafuegos químicos"], "correct": 2, "explanation": "Es el perímetro previsto para contener; combina diversos tipos de barrera."}, {"block": "lineas", "page": 30, "q": "¿Qué persigue la quema de ensanche?", "options": ["Añadir combustible a la LD", "Ampliar y fortalecer la zona sin combustible", "Sustituir siempre toda LC", "Medir el frente"], "correct": 1, "explanation": "Consume intencionadamente combustible para reforzar la línea. Su finalidad se distingue del contrafuego."}, {"block": "organizacion", "page": 24, "q": "Estrategia, táctica y horario responden a…", "options": ["Qué, cómo y cuándo", "Quién, dónde y por qué", "Cuánto, dónde y color", "Tres nombres del ataque directo"], "correct": 0, "explanation": "La estrategia fija objetivos; la táctica cómo ejecutarlos; el horario programa etapas."}, {"block": "organizacion", "page": 32, "q": "¿Cuál es correcta sobre la liquidación?", "options": ["Se inicia solo al día siguiente", "Está prohibida hasta completar vigilancia", "Es sinónimo exacto de control", "Puede comenzar durante otras etapas"], "correct": 3, "explanation": "El material dice que comienza en cualquier momento, por cola/flancos, para crear líneas negras."}, {"block": "peligro", "page": 32, "q": "Regla del 30: ¿qué combinación cumple dos factores?", "options": ["20 °C y 15 km/h", "10 % pendiente y 70 % HR", "35 °C y 25 % HR", "25 °C y 20 % pendiente"], "correct": 2, "explanation": "Temperatura >30 °C y humedad relativa <30 %. La HR lleva desigualdad opuesta a los otros tres factores."}, {"block": "peligro", "page": 34, "q": "La ducha de pavesas se asocia a…", "options": ["Pavesas más ligeras a miles de metros", "Numerosas pavesas más pesadas a corta distancia", "Lluvia que extingue siempre", "Fuego solo de subsuelo"], "correct": 1, "explanation": "El tema distingue decenas de metros y pavesas de mayor peso para focos próximos."}, {"block": "herramientas", "page": 37, "q": "¿Cuál tiene seis dientes y filo opuesto?", "options": ["MacLeod", "Pulaski", "Podón", "Antorcha"], "correct": 0, "explanation": "MacLeod: placa con seis dientes en un lado y corte en el otro."}, {"block": "herramientas", "page": 35, "q": "La mezcla de la antorcha del tema es…", "options": ["98 % gasolina, 2 % aceite", "Solo gasolina", "1/3 gasóleo, 2/3 gasolina", "2/3 gasóleo, 1/3 gasolina"], "correct": 3, "explanation": "La mezcla 98/2 corresponde a motosierra/desbrozadora. Antorcha: dos partes de gasóleo y una de gasolina."}, {"block": "herramientas", "page": 36, "q": "El límite de mochila cargada está expresado en…", "options": ["20 litros", "20 m²", "20 kg", "2,5 kg"], "correct": 2, "explanation": "El temario fija un peso máximo de 20 kg; no lo da como volumen del depósito."}, {"block": "maquinaria", "page": 44, "q": "La mezcla 98/2 del tema significa…", "options": ["98 % aceite, 2 % gasolina", "98 % gasolina, 2 % aceite", "98 % gasóleo, 2 % agua", "98 L siempre por depósito"], "correct": 1, "explanation": "La proporción se expresa en porcentaje; el aceite de cadena se distingue de esta mezcla."}, {"block": "maquinaria", "page": 45, "q": "El traje forestal descrito…", "options": ["No está diseñado para atrapamiento ni riesgos estructurales", "Garantiza seguridad ante atrapamiento", "Sustituye todo EPI de motosierra", "Debe impedir transpiración"], "correct": 0, "explanation": "El tema limita expresamente ese uso del vestuario y pide transpiración por calor metabólico."}, {"block": "seguridad", "page": 52, "q": "¿Qué representan E y L en OACEL?", "options": ["Equipo y luz", "Extinción y liquidación", "Evaluación y ladera", "Ruta de escape y lugar seguro"], "correct": 3, "explanation": "La secuencia del material es observación, atención/anclaje, comunicación, ruta de escape y lugar seguro."}, {"block": "seguridad", "page": 47, "q": "¿Qué combinación contradice el protocolo del helicóptero?", "options": ["Esperar permiso y ser visible", "Herramientas horizontales y prendas sujetas", "Acercarse por la cola desde la parte alta", "De frente, agachado y sin correr"], "correct": 2, "explanation": "El tema prohíbe cola/trasera y punto alto de la ladera; exige permiso de tripulación."}, {"block": "seguridad", "page": 49, "q": "Respecto a la trayectoria de la aeronave, la retirada de la descarga es…", "options": ["Paralela", "En ángulo recto", "Siempre hacia la cola del helicóptero", "Sin relación con trayectoria"], "correct": 1, "explanation": "La p. 49 señala retirada en ángulo recto respecto a la trayectoria de la aeronave."}, {"block": "prediccion", "page": 54, "q": "Subiendo, viento a favor y combustible caliente: ¿alineación?", "options": ["3/3, plena", "2/3, media", "1/3, poca", "0/3, fuera"], "correct": 0, "explanation": "Cada uno de los tres factores está a favor y suma 1."}, {"block": "prediccion", "page": 53, "q": "¿Qué rasgo identifica la quinta generación?", "options": ["Primer fuego de superficie", "Solo continuidad agrícola", "Solo aparición de interfaz", "Simultaneidad de amenazas a varias IUF"], "correct": 3, "explanation": "La cuarta destaca IUF; la quinta añade simultaneidad de grandes incendios y focos que amenazan varias zonas."}, {"block": "prediccion", "page": 53, "q": "¿Qué destaca la sexta generación?", "options": ["Elimina la interacción meteorológica", "Solo incendios pequeños", "Energía capaz de modificar meteorología local", "Una única fecha de temporada"], "correct": 2, "explanation": "El material relaciona aridez extrema y energía liberada con modificación meteorológica y tormentas de fuego."}, {"id": "academia-forestales-1-01", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Con una longitud de la llama de 1,5 m, ¿podemos realizar un ataque directo?", "options": ["Sí", "No", "depende de las condiciones meteorológicas", "depende del modelo de combustible"], "correct": 1, "sourceNumber": 1, "block": "metodos", "page": 14, "extraPages": [25], "explanation": "La clave de la academia es «no». La p. 14 del temario sitúa el ataque directo manual efectivo por debajo de 1,2 m: 1,5 m supera esa referencia y encaja en la fila que considera el directo no efectivo y pide apoyo de otros medios. Esta es la tabla que explica la respuesta del test.", "contrast": "Longitud de llama y altura vertical de la llama son medidas distintas. Además, «ataque directo» describe la actuación sobre el combustible que arde, no un único medio de extinción.", "review": {"title": "Matiz del enunciado y anotación manuscrita", "text": "El enunciado no especifica el medio de ataque. En la p. 25 hay una anotación «longitud de llama < 2 m», distinta de la referencia impresa de 1,2 m en la p. 14. NWCG también distingue el ataque manual —referencia de unos 4 pies, 1,22 m— de la intervención con otros medios. Se conserva la clave de la academia y se hace visible la diferencia entre fuentes.", "links": [{"title": "NWCG · Ataque directo y longitud de llama", "url": "https://training.nwcg.gov/dl/s130/s-130-ig07.pdf"}, {"title": "NWCG · Longitud frente a altura de llama", "url": "https://www.nwcg.gov/publications/pms437/fire-assessment/observing-current-fire-behavior"}]}, "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-02", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Un angledózer puede trabajar en pendientes de hasta:", "options": ["40-50%", "50-60%", "30-40%", "35-45%"], "correct": 1, "sourceNumber": 2, "block": "maquinaria", "page": 44, "explanation": "El intervalo de referencia que dan la academia y el temario para el angledózer es 50–60 % de pendiente. Es una limitación que el material relaciona con el empleo de maquinaria pesada, junto con el acceso, el traslado y el peso de la máquina.", "contrast": "El dato está expresado en porcentaje de pendiente, no en grados: una pendiente del 60 % no equivale a 60°. Los demás intervalos no son el que figura en este material.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-03", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Qué proporción de combustible usaremos en una motosierra?", "options": ["95% de gasolina y 5% de aceite", "98% de gasolina y 2% de aceite", "1/3 de aceite y 2/3 de gasolina", "1/3 de gasoil y 2/3 de gasolina"], "correct": 1, "sourceNumber": 3, "block": "maquinaria", "page": 44, "explanation": "La mezcla indicada en este temario es 98 % de gasolina y 2 % de aceite. Por ejemplo, 1 litro de mezcla contiene 980 ml de gasolina y 20 ml de aceite. La motosierra lleva, además, un depósito de aceite específico para lubricar la cadena.", "contrast": "No confundas esta mezcla con la antorcha de goteo, que el material describe con gasolina y gasóleo en proporción 1/3 y 2/3, respectivamente.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-04", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Qué es lo que explica el viento Foehn?", "options": ["proceso adiabático", "escala de Beaufort", "inversión térmica", "el tipo de vegetación"], "correct": 0, "sourceNumber": 4, "block": "meteorologia", "page": 18, "explanation": "El Foehn se explica por los cambios térmicos asociados al ascenso y descenso del aire sobre un relieve: al ascender, el aire se expande y se enfría; al descender, se comprime y se calienta. La condensación y la pérdida de humedad en barlovento contribuyen a que llegue más cálido y seco a sotavento.", "contrast": "Beaufort clasifica la intensidad del viento. La inversión térmica describe una distribución de temperatura con la altura; no es el proceso que explica el Foehn.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-05", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cómo se llama la temperatura a la qué debe enfriar el aire para llegar al punto de saturación?", "options": ["gradiente vertical húmeda", "gradiente vertical seca", "efecto Foehn", "punto de rocío"], "correct": 3, "sourceNumber": 5, "block": "meteorologia", "page": 20, "explanation": "El punto de rocío es la temperatura a la que el aire alcanza la saturación al enfriarse sin cambiar su contenido de vapor de agua. En ese punto la humedad relativa llega al 100 % y puede comenzar la condensación.", "contrast": "Los gradientes son variaciones de temperatura por unidad de altura, expresadas aquí en °C/100 m. El punto de rocío es una temperatura, no un gradiente.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-06", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "La gradiente vertical seca es de:", "options": ["-0,6 °C cada 100 m", "-0,6 °C cada 10 m", "entre -0,4 y 1 °C cada 10 m", "-1 °C cada 100 m"], "correct": 3, "sourceNumber": 6, "block": "meteorologia", "page": 20, "explanation": "El gradiente adiabático seco de referencia es aproximadamente −1 °C por cada 100 m de ascenso de una parcela de aire no saturada. Si desciende, la parcela se calienta aproximadamente a ese ritmo.", "contrast": "El −0,6 °C/100 m corresponde al gradiente normal de referencia del temario. Cambiar 100 m por 10 m multiplica por diez la variación y hace incorrecto el distractor.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-07", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "En una inversión térmica, ¿ a qué altura se sitúa el cinturón térmico?", "options": ["a 1/3 del fondo del valle", "a la mitad del fondo del valle", "a 2/3 del fondo del valle", "a ¾ del fondo del valle"], "correct": 2, "sourceNumber": 7, "block": "meteorologia", "page": 17, "explanation": "El material sitúa el cinturón térmico hacia los 2/3 desde el fondo del valle. Durante la inversión, el aire frío se acumula en las zonas bajas y queda por debajo de una banda más cálida: esa banda es el cinturón térmico.", "contrast": "La respuesta reproduce la posición esquemática del apunte y de la academia; no es una altura fija que deba cumplirse en todos los valles. No confundas la banda cálida con la bolsa de aire frío del fondo.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-08", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Una velocidad de propagación de 75 m/min es:", "options": ["extrema", "muy alta", "lenta", "alta"], "correct": 0, "sourceNumber": 8, "block": "magnitudes", "page": 14, "explanation": "En la escala del temario, una propagación superior a 10 m/min se clasifica como extrema. Por tanto, 75 m/min está claramente en esa categoría. La conversión es 75 × 60 = 4.500 m/h, es decir, 4,5 km/h.", "contrast": "La categoría alta corresponde al intervalo 2–10 m/min. «Muy alta» no es la denominación de la categoría superior en la tabla utilizada por este test.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-09", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Según la clasificación del combustible por tamaño y tiempo de retardación, ¿cuánto tiempo de retardación tendría si su tamaño es de 30 mm?", "options": ["1 hora", "10 horas", "100 horas", "1.000 horas"], "correct": 2, "sourceNumber": 9, "block": "combustibles", "page": 13, "explanation": "30 mm cae dentro del intervalo 25–75 mm: combustible mediano, asociado en el material a 100 horas de retardación. Primero localiza el tamaño en la tabla y después recupera su tiempo.", "contrast": "La serie es < 5 mm → 1 h; 5–25 mm → 10 h; 25–75 mm → 100 h; > 75 mm → 1.000 h. El tiempo de retardación describe el ajuste de humedad, no cuánto tarda en consumirse el combustible.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-10", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cuánto tiene que caer la humedad del combustible vegetal para qué esté disponible para arder?", "options": ["por debajo del 15-20%", "por debajo del 15-25%", "por debajo del 20-30%", "por debajo del 25-35%"], "correct": 1, "sourceNumber": 10, "block": "combustibles", "page": 13, "explanation": "El intervalo que da este material para la disponibilidad del combustible vegetal es una humedad por debajo del 15–25 %. Es humedad del combustible, expresada respecto de su peso seco, y no humedad relativa del aire.", "contrast": "No confundas este intervalo de combustible con la humedad relativa < 30 % de la regla del 30. Los límites de humedad de extinción varían con el combustible; aquí se pregunta el dato de los apuntes.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-11", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cómo consideramos una cantidad de combustible de 25 t/ha?", "options": ["desecho de bosque o clareo", "pasto y arbusto", "desierto", "matorral"], "correct": 3, "sourceNumber": 11, "block": "combustibles", "page": 12, "explanation": "La carga de 25 t/ha encaja en el intervalo de matorral del material: 20–100 t/ha. Como conversión, 25 t/ha equivalen a 2,5 kg/m² de masa seca.", "contrast": "La tabla cita desierto 0–3 t/ha; pasto y arbusto 2–12; matorral 20–100; y cargas de referencia superiores para restos de clareo o explotación. La pregunta utiliza esa tabla, no identifica una vegetación solo por su masa en cualquier contexto.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-12", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Una quéma de matorral autorizada se considera:", "options": ["Incendio controlado", "Incendio forestal", "Incendio autorizado", "No se considera incendio"], "correct": 3, "sourceNumber": 12, "block": "bases", "page": 11, "explanation": "Una quema autorizada, prevista y mantenida bajo control no se considera incendio forestal en la definición del tema: se trata de vegetación destinada a arder. El incendio forestal implica propagación sin control sobre vegetación que no estaba destinada a quemarse.", "contrast": "La autorización no evita que una quema pueda originar un incendio si se escapa de control. La respuesta presupone que la quema se ejecuta dentro de las condiciones previstas.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-13", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿A partir de que temperatura entran en combustión los gases de la madera?", "options": ["300 °C", "600 °C", "200 °C", "80 °C"], "correct": 0, "sourceNumber": 13, "block": "bases", "page": 5, "explanation": "El temario sitúa la combustión de los gases de la madera alrededor de 300 °C. Es la combustión gaseosa que produce las llamas y forma el frente visible del incendio.", "contrast": "200 °C se asocia a la destilación de resinas; por encima de 600 °C, a la combustión del carbón. Son referencias de fases distintas, no temperaturas intercambiables.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-14", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cuál de estos es un incendio especialmente peligroso?", "options": ["El que se escapa de un ataque ampliado con duración superior a 24 horas o superficie afectada superior a 100 ha", "El que se escapa de un ataque directo con duración superior a 48 horas o superficie afectada superior a 100 ha", "El que se escapa de un ataque directo con duración superior a 24 horas o superficie quemada superior a 100 ha", "El que se escapa al ataque ampliado con duración superior a 48 horas o superficie afectada superior a 100 ha"], "correct": 3, "sourceNumber": 14, "block": "peligro", "page": 52, "explanation": "La opción que reproduce el criterio de las notas es: incendio que escapa al ataque ampliado, con duración superior a 48 horas o superficie afectada superior a 100 ha. La estructura que debes recordar es «ataque ampliado + (más de 48 h O más de 100 ha)».", "contrast": "Los distractores cambian ampliado por directo o 48 horas por 24. La conjunción es «o»: el enunciado no exige superar a la vez ambos umbrales. El dato de 500 ha aparece por separado en el material.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-15", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Si tenemos una autorización de quema con el número 2 y el índice de riesgo publicado es el 3, ¿podemos realizar la quéma?", "options": ["No", "si, siempre que nos encontremos a más de 15 metros de una zona arbolada", "Sí", "si, siempre que según las escala del 30 no nos indique que el incendio pueda ser peligroso"], "correct": 0, "sourceNumber": 15, "block": "peligro", "page": 52, "explanation": "Según la regla numérica que acompaña al test, el valor de la autorización debe ser igual o superior al índice publicado. Con autorización 2 e índice 3, la condición 2 ≥ 3 no se cumple: la respuesta es «no».", "contrast": "Ni alejarse 15 metros del arbolado ni cumplir aisladamente la regla del 30 modifica los valores permitidos por la autorización.", "review": {"title": "Alcance de la regla del test", "text": "La comparación numérica procede de la explicación de la academia y del díptico IRIF de 2017. El anexo I de la Resolución de 3 de septiembre de 2024 establece que cada autorización debe indicar expresamente los valores de IRIF con los que permite la quema. Para interpretar una autorización concreta, hay que comprobar esos valores y las restricciones aplicables; la desigualdad del test no resume toda la regulación.", "links": [{"title": "Principado de Asturias · Díptico IRIF de 2017", "url": "https://www.asturias.es/Asturias/descargas/PDF_TEMAS/Agricultura/Politica%20Forestal/incendios/2017_01_10_diptico_IRIF.pdf"}, {"title": "Principado de Asturias · Uso del fuego y normativa", "url": "https://www.asturias.es/temas/agricultura-gestion-forestal/incendios-forestales-prevencion/uso-del-fuego"}]}, "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-16", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cómo llamamos a los bordes de lo quemado sin posibilidad de reproducirse?", "options": ["perímetro", "borde", "líneas negras", "línea de fuego"], "correct": 2, "sourceNumber": 16, "block": "lineas", "page": 52, "explanation": "Las líneas negras son bordes de terreno ya quemado en los que se ha eliminado la posibilidad de reproducción del fuego, según la definición del material. Se relacionan con la liquidación y el aseguramiento del perímetro.", "contrast": "Perímetro solo nombra el contorno. Línea de fuego se refiere al borde con combustión activa. Para responder «línea negra» es decisivo el matiz «sin posibilidad de reproducirse».", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-17", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cómo se llama el dispositivo que permite al helicóptero echar agua en un incendio forestal?", "options": ["cambi", "cesta", "balde", "helibalde"], "correct": 3, "sourceNumber": 17, "block": "seguridad", "page": 50, "explanation": "El dispositivo suspendido del helicóptero para transportar y descargar agua se denomina helibalde. El material también lo identifica como bambi bucket.", "contrast": "«Balde» es un nombre genérico; helibalde es la denominación específica que pide el test para el equipo aéreo.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-18", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Formas de un incendio forestal:", "options": ["circular, irregular y elíptico", "ovalado, irregular y triangular", "regular e irregular", "regular, irregular y circular"], "correct": 0, "sourceNumber": 18, "block": "anatomia", "page": 8, "explanation": "Las formas que distingue el temario son circular, elíptica e irregular. La circular se asocia a propagación más uniforme; viento o pendiente dominantes pueden alargar la forma; la heterogeneidad de combustible y relieve favorece perímetros irregulares.", "contrast": "El test pregunta esta clasificación de formas. No la confundas con las partes del incendio —cabeza, flancos y cola— ni con los tipos por estrato —subsuelo, superficie y copas—.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-19", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cuál es el peso máximo de una mochila extintor?", "options": ["15 kg", "20 kg", "25 kg", "30 kg"], "correct": 1, "sourceNumber": 19, "block": "herramientas", "page": 36, "explanation": "El peso máximo indicado para la mochila extintora cargada es 20 kg. La explicación de la academia lo relaciona con el límite de masa de un extintor portátil.", "contrast": "Se pregunta por masa, no por capacidad: 20 kg no significa un depósito de 20 litros de agua, porque también pesa la propia mochila y su equipo.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-20", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Qué es un Pulaski?", "options": ["Un helicóptero polaco de extinción de incendios", "una herramienta con 6 dientes en un lado y corte en el opuesto", "una herramienta con una azada y un pico", "una herramienta con un hacha y una azada"], "correct": 3, "sourceNumber": 20, "block": "herramientas", "page": 36, "explanation": "El Pulaski combina un hacha y una azada en la misma cabeza. Permite cortar vegetación y raíces, y trabajar el suelo en la construcción de líneas de defensa.", "contrast": "La herramienta con seis dientes por un lado y filo por el opuesto es el MacLeod. Hacha–azada → Pulaski; rastrillo–azada → MacLeod.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-21", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Qué proporción de combustible contiene una antorcha de goteo?", "options": ["1/3 de gasolina y 2/3 de gasoil", "1/3 de gasoil y 2/3 de gasolina", "½ de gasolina y ½ de gasoil", "gasolina con un 5% de aceite"], "correct": 0, "sourceNumber": 21, "block": "herramientas", "page": 35, "explanation": "La mezcla de la antorcha descrita en el material es una parte de gasolina por dos de gasóleo: 1/3 y 2/3, respectivamente. La gasolina facilita el encendido y el gasóleo contribuye a mantener la combustión del combustible goteado.", "contrast": "No inviertas las fracciones. La mezcla 98 % gasolina + 2 % aceite corresponde a la motosierra o desbrozadora del temario, no a la antorcha.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-22", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Con qué parte del batefuego se realiza la extinción de fuego?", "options": ["Con la parte de las estrías", "Con la parte plana", "Con cualquiera de las dos partes", "ninguna es correcta"], "correct": 1, "sourceNumber": 22, "block": "herramientas", "page": 35, "explanation": "En el batefuegos descrito se utiliza la parte plana de la pala para trabajar sobre la base de la llama. El mecanismo estudiado es la sofocación, al separar el aire de la zona de combustión.", "contrast": "El distractor de las estrías cambia la cara de trabajo que pide la academia. No confundas la parte de la herramienta empleada —cara plana— con el mecanismo de extinción —sofocación—.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-23", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "La gradiente vertical normal está próxima a:", "options": ["-1 °C cada 100 m", "entre -0,4 °C y 1 °C cada 100 m", "-0,6 °C cada 100 m", "entre 0,6 °C y 1 °C cada 100 m"], "correct": 2, "sourceNumber": 23, "block": "meteorologia", "page": 20, "explanation": "El gradiente vertical normal de referencia del temario es aproximadamente −0,6 °C por cada 100 m de aumento de altura. Por ejemplo, 500 m representan una disminución de referencia de 3 °C.", "contrast": "No lo confundas con el gradiente adiabático seco de −1 °C/100 m. El gradiente normal describe una referencia de la atmósfera; el seco describe el cambio de una parcela no saturada que asciende o desciende.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-24", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Según la escala de Beaufort, ¿a qué número de esta escala pertenece un viento de 50 km/h?", "options": ["7", "10", "5", "11"], "correct": 0, "sourceNumber": 24, "block": "meteorologia", "page": 20, "explanation": "50 km/h es el extremo inferior del grado 7 de Beaufort en la tabla del temario: 50–61 km/h, denominado frescachón. El grado 6 llega hasta 49 km/h.", "contrast": "Beaufort es una escala de fuerza del viento: el número 7 no son 7 km/h. Mantén la unidad de la columna, porque las tablas pueden incluir también nudos o m/s.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-25", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "En un incendio de suelo, ¿que anchura debe de tener la línea de defensa?", "options": ["de 0,50 m a 3 m", "de 0,15 m a 4 m", "de 0,15 m a 3 m"], "correct": 1, "sourceNumber": 25, "block": "lineas", "page": 21, "explanation": "La academia marca 0,15–4 m para el incendio de suelo. Ese mismo intervalo aparece escrito en la p. 21 del temario. Es la opción que conserva ambos extremos: 0,15 m por abajo y 4 m por arriba.", "contrast": "En la misma tabla, subsuelo figura con 30 cm y copas con 4–10 m. No cambies de fila al memorizar las anchuras.", "review": {"title": "Cifra del material a contrastar", "text": "El resumen ya señalaba el extremo inferior de 0,15 m como una cifra a contrastar. Que el test repita ese valor permite identificar su clave, pero no resuelve por sí solo la duda del dato. Se mantiene la reserva y la referencia a la imagen original.", "links": []}, "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-26", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "En un incendio donde tenemos 29 °C de temperatura ambiente, una pendiente de 45%, una humedad relativa de 21% y un viento de 32 km/h, como calificaríamos esta situación:", "options": ["Leve", "Moderada", "Controlada", "Peligrosa"], "correct": 3, "sourceNumber": 26, "block": "peligro", "page": 32, "explanation": "Cumple tres factores de la regla del 30: pendiente 45 % > 30 %, humedad relativa 21 % < 30 % y viento 32 km/h > 30 km/h. La temperatura, 29 °C, no supera 30 °C. El material considera peligrosa la concurrencia de dos o más factores; aquí hay tres.", "contrast": "En temperatura, viento y pendiente se supera 30; en humedad relativa se baja de 30. El signo de la humedad es el contrario.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-27", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Según la escala de Rothermel un matorral denso y verde de menos de 1 m de altura corresponde al modelo:", "options": ["5", "7", "10", "13"], "correct": 0, "sourceNumber": 27, "block": "combustibles", "page": 12, "explanation": "El modelo 5 de Rothermel corresponde en el material a matorral denso y verde de menos de 1 m. Está dentro de la familia de matorral, modelos 4–7.", "contrast": "La Ola de tu casillero, número 5, puede cubrir un matorral verde y bajo. Modelo 4: matorral muy denso de más de 2 m; modelo 7: matorral muy inflamable. Modelos 10 y 13 pertenecen a otras familias.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-28", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "La temperatura a la cual la madera comienza a destilar las resinas es:", "options": ["100 °C", "200 °C", "300 °C", "600 °C"], "correct": 1, "sourceNumber": 28, "block": "bases", "page": 5, "explanation": "El temario sitúa el inicio de la destilación de resinas alrededor de 200 °C. Es un dato asociado al calentamiento y a la liberación de sustancias volátiles, anterior a la referencia de combustión gaseosa de 300 °C.", "contrast": "Secuencia de referencias del material: 100 °C → eliminación de humedad; 200 °C → resinas; 300 °C → gases ardiendo; más de 600 °C → combustión del carbón.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-29", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "¿Cuál es el método de ataque mas peligroso para los bomberos?", "options": ["El ataque directo", "El ataque en paralelo", "El ataque en pinza", "El contrafuego"], "correct": 1, "sourceNumber": 29, "block": "metodos", "page": 27, "explanation": "El método señalado como más peligroso para el personal en este temario es el ataque paralelo. Se trabaja próximo al frente, abriendo y apoyando una faja en paralelo al avance, con tratamiento del combustible entre los bordes.", "contrast": "La pregunta pide la caracterización del material, no una clasificación universal del riesgo de cualquier operación. No cambies la respuesta a contrafuego solo porque este también requiera planificación y control específicos.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-1-30", "origin": "academia", "sourceTest": "Incendios forestales 1", "q": "Los vientos ascendentes se producen:", "options": ["Durante la noche", "Al atardecer", "Durante el día", "Al amanecer"], "correct": 2, "sourceNumber": 30, "block": "meteorologia", "page": 20, "explanation": "La regla de vientos locales del material es: ascendentes durante el día y descendentes durante la noche. El calentamiento diurno de las laderas favorece el ascenso; el enfriamiento nocturno favorece el drenaje de aire frío hacia las zonas bajas.", "contrast": "Se está preguntando por el ciclo local de ladera. El viento general puede superponerse y modificar la situación observada; la respuesta del test corresponde al esquema diurno/nocturno.", "test": "academia-1", "sourceLabel": "Academia · Forestales 1"}, {"id": "academia-forestales-2-01", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Según el estrato afectado, los incendios forestales se clasifican en:", "options": ["copas, superficie y subsuelo", "árboles, arbustos y hierbas", "coníferas, frondosas y arbustivas", "altos, medios y bajos"], "correct": 0, "sourceNumber": 1, "block": "tipos", "page": 8, "explanation": "La clasificación por estrato distingue dónde se produce la combustión: subsuelo, superficie y copas. Subsuelo afecta a la materia orgánica bajo la superficie; superficie, a hierbas, hojarasca y matorral; copas, a la parte alta del arbolado.", "contrast": "No es una clasificación por forma del perímetro ni por grupo botánico. Árboles, arbustos y hierbas describen vegetación, pero no sustituyen los tres estratos de esta clasificación."}, {"id": "academia-forestales-2-02", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "¿Qué tipo de vegetación en su conjunto forman una barrera resistente al fuego?", "options": ["hidrófitas", "pirófita activa", "ninguna es correcta", "por un igual las hidrófitas y las pirófitas activas"], "correct": 0, "sourceNumber": 2, "block": "combustibles", "page": null, "explanation": "La academia identifica las hidrófitas como la vegetación que, agrupada, forma una barrera resistente al fuego. La asociación de estudio es hidro → agua y ambientes húmedos → mayor resistencia a la propagación en el contexto de esta pregunta.", "contrast": "La adaptación de una planta al fuego no equivale a formar una barrera contra él. Las pirófitas activas se relacionan en este test con una regeneración estimulada por el fuego."}, {"id": "academia-forestales-2-03", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "La recurrencia en los incendios forestales en un mismo lugar afecta a las especies vegetales del mismo modo que favorece a:", "options": ["que la vegetación instalada en la zona sea cada vez menos pirófila", "que las especies mejor adaptadas al fuego sean las predominantes", "la supervivencia, crecimiento y reproducción de plantas", "no favorece en nada"], "correct": 1, "sourceNumber": 3, "block": "combustibles", "page": null, "explanation": "La recurrencia del fuego actúa como un filtro: en el esquema que pregunta la academia, favorece el predominio de especies mejor adaptadas a sobrevivir o regenerarse después del incendio. Por eso la clave no es una vegetación cada vez menos pirófila.", "contrast": "No significa que todo incendio beneficie a todas las plantas. La pregunta trata de qué adaptaciones resultan favorecidas por la repetición del fuego, no de ausencia de daños."}, {"id": "academia-forestales-2-04", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Las laderas con orientación a la solana tienen:", "options": ["mayor temperatura, menor humedad y menor superficie que las zonas de umbría", "menor humedad y menor vegetación que las zonas de umbría", "mayor temperatura y menor vegetación que las zonas de umbría", "mayor temperatura, menor humedad y menor vegetación que las zonas de umbría"], "correct": 3, "sourceNumber": 4, "block": "topografia", "page": 16, "explanation": "En el esquema general del material, la solana recibe más radiación solar y presenta mayor temperatura, menor humedad y menor vegetación que la umbría. La opción correcta reúne los tres rasgos que pide el test.", "contrast": "Los distractores que solo mencionan dos rasgos resultan incompletos. La orientación de una ladera tampoco implica por sí sola que tenga menor superficie: ese añadido hace incorrecta la primera opción."}, {"id": "academia-forestales-2-05", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Un combustible leñoso genera:", "options": ["más intensidad calorífica", "más llamas", "más humo", "más llamas y más humo"], "correct": 0, "sourceNumber": 5, "block": "combustibles", "page": null, "explanation": "La clave de la academia asocia el combustible leñoso con más intensidad calorífica. Lo que se pregunta es el efecto térmico que atribuye a ese tipo de combustible, no la cantidad de humo o el número de llamas visibles.", "contrast": "Intensidad, longitud de llama y producción de humo son conceptos distintos. El enunciado no precisa con qué combustible se compara; conserva esta asociación como criterio del test, sin inferir una intensidad fija para toda madera."}, {"id": "academia-forestales-2-06", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Un fuego de roble y encina la llama será de color:", "options": ["verde", "amarillo", "azul", "naranja"], "correct": 2, "sourceNumber": 6, "block": "combustibles", "page": null, "explanation": "La clave proporcionada por la academia es azul para la llama de un fuego de roble y encina. Para este test, la asociación que se evalúa es roble/encina → llama azul; el objeto de la pregunta es la llama, no el humo.", "contrast": "No mezcles esta asociación con la pregunta de humo de pinos. Son dos claves diferentes y no permiten deducir una especie a partir de un único color.", "review": {"title": "Asociación de la academia pendiente de contraste", "text": "Esta asociación de color no está documentada en las páginas del temario que se han comprobado. Se conserva como clave del cuestionario compartido y se identifica su alcance, sin inventar una explicación química ni presentarla como regla universal de identificación de especies.", "links": []}}, {"id": "academia-forestales-2-07", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El fuego de pinos producirá humos de color:", "options": ["gris", "amarillo", "azul", "negro"], "correct": 1, "sourceNumber": 7, "block": "combustibles", "page": null, "explanation": "La academia marca amarillo para el humo de un fuego de pinos. La pareja que pide este cuestionario es pinos → humo amarillo. El enunciado habla del humo; no pregunta por el color de las llamas.", "contrast": "La pregunta anterior relaciona roble y encina con llama azul en la clave de la academia. Mantén separados combustible, fenómeno observado y color.", "review": {"title": "Asociación de la academia pendiente de contraste", "text": "La clave de color procede del test resuelto. No se ha encontrado una justificación de esa asociación en las páginas aportadas que se han comprobado, por lo que se mantiene identificada como criterio de la academia y no como una señal exclusiva de un tipo de vegetación.", "links": []}}, {"id": "academia-forestales-2-08", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "La velocidad del frente se duplica:", "options": ["en pendientes del 10%", "en pendientes del 20%", "en pendientes del 30%", "ninguna es correcta"], "correct": 0, "sourceNumber": 8, "block": "topografia", "page": 16, "explanation": "La respuesta que da la academia es una pendiente del 10 %. La relación cualitativa sí está en tus apuntes: ladera arriba, la pendiente acerca el combustible al frente y favorece su precalentamiento por radiación y convección, aumentando la propagación.", "contrast": "La pendiente está expresada en porcentaje, no en grados. El «doble» es un multiplicador de velocidad, no una categoría de intensidad del incendio.", "review": {"title": "El factor de duplicación necesita contexto", "text": "La p. 16 no establece una duplicación universal al alcanzar el 10 %. NWCG explica que el efecto sobre la propagación depende de la pendiente de partida, el viento y los combustibles. Se conserva 10 % como clave de este test, pero la regla cuantitativa queda señalada para contrastar con la academia.", "links": [{"title": "NWCG · Efecto de la pendiente en la propagación", "url": "https://www.nwcg.gov/course/ffm/fire-behavior/firefighter-math-87-slope-effect-on-ros"}]}}, {"id": "academia-forestales-2-09", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El fenómeno de la vegetación de generación de brotes estimulados por el fuego, se define como:", "options": ["pirófita pasiva", "pirófita activa", "hidrofitas", "ninguna es correcta"], "correct": 1, "sourceNumber": 9, "block": "combustibles", "page": null, "explanation": "En el vocabulario que utiliza la academia, pirófita activa es la que presenta regeneración o brotes estimulados por el fuego. El matiz decisivo es que el fuego activa la respuesta de regeneración, no solo que la planta pueda resistirlo.", "contrast": "Activa → estímulo de regeneración; pasiva → resistencia o supervivencia frente al fuego. Las hidrófitas se relacionan con el agua y los ambientes húmedos."}, {"id": "academia-forestales-2-10", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Indica el fenómeno que ayuda a que se produzca la inversión térmica", "options": ["relieve", "viento", "solana", "solana y umbría"], "correct": 0, "sourceNumber": 10, "block": "meteorologia", "page": 17, "explanation": "El relieve de un valle cerrado y resguardado favorece la inversión: el aire frío desciende por las laderas y se acumula en el fondo, por debajo de capas más cálidas. Por eso el relieve es la opción que explica la configuración del fenómeno en este material.", "contrast": "Solana y umbría describen exposición solar. La pregunta se centra en la acumulación de aire frío facilitada por la forma del terreno, no en la clasificación de orientaciones."}, {"id": "academia-forestales-2-11", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "La forma más correcta de aplicar el agua a través de la lanza en un incendio forestal para conseguir una mayor penetración en el borde del incendio es:", "options": ["con la pantalla de protección", "con el cono abierto para obtener un mayor alcance de la zona a extinguir", "con agua pulverizada", "con el chorro sólido"], "correct": 3, "sourceNumber": 11, "block": "tecnicas", "page": 22, "explanation": "Para conseguir mayor penetración en el borde, la clave es el chorro sólido: concentra el agua sobre una zona y favorece su entrada en el combustible. La palabra que decide la respuesta es penetración.", "contrast": "La pulverización distribuye el agua en gotas y aumenta la superficie de intercambio térmico. Un cono abierto o una pantalla no equivale a un chorro concentrado para penetrar."}, {"id": "academia-forestales-2-12", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "¿Cómo hay que aplicar un contrafuego?", "options": ["de arriba hacia abajo", "de abajo hacia arriba", "siempre en la cabeza del frente de llamas", "ninguna es correcta"], "correct": 0, "sourceNumber": 12, "block": "metodos", "page": 26, "extraPages": [27], "explanation": "La clave de este cuestionario es de arriba hacia abajo. La pregunta da una dirección genérica, pero el contrafuego del temario se define por una dirección y un momento prefijados dentro del plan, según combustible, topografía y meteorología.", "contrast": "No se aplica siempre en la cabeza del incendio por definición. La orden corresponde al Director de Extinción y el material exige que no haya personas entre ambos fuegos.", "review": {"title": "Dirección simplificada en el enunciado", "text": "Las páginas 26–27 no establecen «arriba hacia abajo» como una regla válida para cualquier contrafuego. Se conserva la respuesta marcada por la academia, diferenciándola de las condiciones y la dirección concreta que debe fijar el plan de la operación.", "links": []}}, {"id": "academia-forestales-2-13", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "¿Cómo actúa la tierra como método de extinción?", "options": ["sofocando el fuego actuando sobre el comburente", "no es un método efectivo", "sofocando y enfriando", "desalimentando el combustible"], "correct": 2, "sourceNumber": 13, "block": "tecnicas", "page": 22, "explanation": "La tierra puede sofocar al cubrir el combustible y separarlo del aire, y también contribuir al enfriamiento al absorber calor. Por eso, entre las respuestas propuestas, sofocando y enfriando es la más completa y coincide con la clave de la academia.", "contrast": "La opción que menciona solo el comburente describe un efecto pero omite el otro que pregunta el test. Desalimentación significa retirar combustible; no es lo mismo que cubrirlo con tierra."}, {"id": "academia-forestales-2-14", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "¿Qué anchura como mínimo debe de tener una línea de defensa de un fuego de subsuelo?", "options": ["20 cm hasta descubrir la cubierta vegetal", "30 cm hasta descubrir la cubierta vegetal", "de 30 a 40 cm", "de 20 a 30 cm"], "correct": 1, "sourceNumber": 14, "block": "lineas", "page": 21, "extraPages": [29], "explanation": "La clave de la academia es la opción de 30 cm. La tabla de la p. 21 también atribuye 30 cm a la línea de defensa en fuego de subsuelo. Para cortar la continuidad de la materia orgánica, el material exige alcanzar suelo mineral.", "contrast": "No confundas la anchura de la línea con la profundidad necesaria para eliminar la capa orgánica. La tabla da dimensiones distintas para subsuelo, suelo y copas.", "review": {"title": "La redacción de la opción es imprecisa", "text": "Se conserva la opción «30 cm hasta descubrir la cubierta vegetal» porque es la marcada por la academia. Sin embargo, «descubrir la cubierta vegetal» no expresa correctamente el objetivo técnico: retirar la materia orgánica hasta descubrir suelo mineral, como precisa el temario. La medida y esa redacción deben estudiarse por separado.", "links": []}}, {"id": "academia-forestales-2-15", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "¿En qué etapa del incendio realizaremos un cortafuego?", "options": ["cuando no podamos realizar un ataque directo", "cuando la previsión del incendio es que se nos vaya fuera de control", "cuando el terreno y la vegetación nos lo permitan", "en ninguna"], "correct": 3, "sourceNumber": 15, "block": "tecnicas", "page": 21, "explanation": "En ninguna etapa del incendio, según la distinción del material: el cortafuego es una actuación preventiva ejecutada antes. Durante el incendio se construyen líneas de defensa. La propia corrección de la academia explica esa diferencia temporal.", "contrast": "Las otras opciones describen circunstancias del combate, pero no cambian el carácter preventivo que el temario atribuye al cortafuego."}, {"id": "academia-forestales-2-16", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El ataque que desplaza la línea de fuego a corta distancia es:", "options": ["ataque paralelo", "ataque en pinza", "ataque indirecto", "ataque directo"], "correct": 0, "sourceNumber": 16, "block": "metodos", "page": 27, "explanation": "El ataque paralelo trabaja próximo al frente y avanza con una faja o línea en paralelo a él, a corta distancia. Ese desplazamiento cercano es el rasgo con el que la academia identifica el método.", "contrast": "El directo actúa sobre la línea de fuego; el indirecto prepara el control a mayor distancia. La pinza describe la actuación sobre ambos flancos, no este criterio de distancia."}, {"id": "academia-forestales-2-17", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El peso de un batefuego es:", "options": ["igual o inferior a 2,5 kg", "igual o inferior a 2 kg", "igual o inferior a 1,5 kg", "igual o inferior a 1 kg"], "correct": 0, "sourceNumber": 17, "block": "herramientas", "page": 35, "explanation": "El peso máximo de referencia del batefuegos descrito es 2,5 kg: la opción correcta dice igual o inferior a esa cifra. Se pregunta el límite de la herramienta del temario, no el peso que deba tener cualquier modelo comercial.", "contrast": "No confundas sus 2,5 kg con el peso aproximado de 2 kg de otras herramientas del material o con los 20 kg de la mochila cargada."}, {"id": "academia-forestales-2-18", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "La capacidad del depósito del mechero forestal es de:", "options": ["5 L", "6 L", "4 L", "3,5 L"], "correct": 0, "sourceNumber": 18, "block": "herramientas", "page": 35, "explanation": "El mechero forestal o antorcha de goteo del material tiene un depósito de unos 5 litros. Esa capacidad corresponde al equipo descrito y coincide con la clave del test.", "contrast": "Capacidad y proporción son datos distintos: 5 L es el volumen del depósito; 1/3 gasolina y 2/3 gasóleo es la composición de la mezcla indicada."}, {"id": "academia-forestales-2-19", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El ancho de pala de un batefuego es de:", "options": ["20 cm", "25 cm", "30 cm", "35 cm"], "correct": 2, "sourceNumber": 19, "block": "herramientas", "page": 35, "explanation": "El ancho de la pala del batefuegos que describe el temario es 30 cm. La longitud total de la herramienta es de unos 2 m; no son la misma medida.", "contrast": "Asocia cada cifra a su dimensión: pala → 30 cm; herramienta → 2 m; masa máxima → 2,5 kg. Así evitas intercambiar ancho, longitud y peso."}, {"id": "academia-forestales-2-20", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "En el tronzado de un tronco apoyado en los dos extremos, existe riesgo de atasco de la cadena, por lo que debemos:", "options": ["comenzar cortando desde arriba hasta terminar el corte", "comenzar cortando desde abajo hasta terminar el corte", "comenzar cortando desde abajo y terminar desde arriba", "comenzar cortando desde arriba y terminar desde abajo"], "correct": 3, "sourceNumber": 20, "block": "maquinaria", "page": 42, "explanation": "En el esquema del temario, para un tronco apoyado en ambos extremos se empieza por arriba y se termina por abajo. El primer corte trabaja la zona superior de compresión y el segundo la zona inferior de tensión, reduciendo el riesgo de que el cierre del corte aprisione la cadena.", "contrast": "Para el caso del tronco apoyado solo en un extremo, el material invierte el orden: primero abajo y después arriba. La posición de los apoyos es el dato que distingue ambas preguntas."}, {"id": "academia-forestales-2-21", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Para los desplazamientos con la motosierra debemos:", "options": ["transportarla con el motor parado, la cadena con el freno y la espada hacia atrás", "con el freno puesto y la espada hacia atrás", "con el motor parado y la espada hacia atrás", "con el freno puesto y la espada siempre hacia delante"], "correct": 0, "sourceNumber": 21, "block": "maquinaria", "page": 43, "explanation": "La opción completa reúne motor parado, freno de cadena activado y espada hacia atrás. Son las tres condiciones de transporte que enumera el material. Para desplazamientos largos también menciona la funda de la espada.", "contrast": "Las opciones que solo dicen freno o motor parado omiten una de las condiciones. La espada hacia delante contradice la orientación indicada en los apuntes."}, {"id": "academia-forestales-2-22", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Si nos vemos en la situación de que la descarga de agua del helicóptero nos va a caer encima:", "options": ["hay que correr ladera arriba", "hay que correr ladera abajo", "echarse en el suelo y la cabeza hacia donde viene la aeronave", "echarse en el suelo y los pies hacia donde viene la aeronave"], "correct": 2, "sourceNumber": 22, "block": "seguridad", "page": 49, "explanation": "Para la situación de exposición inevitable descrita, el material indica echarse boca abajo con la cabeza hacia la aeronave. La opción correcta conserva esa orientación; el protocolo añade protección de cabeza y casco, y herramientas separadas.", "contrast": "Es distinto de la retirada preventiva del lugar previsto para la descarga, que el temario describe en ángulo recto respecto a la trayectoria. No confundas ambos momentos."}, {"id": "academia-forestales-2-23", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El acercamiento al helicóptero se debe de realizar:", "options": ["por la parte delantera o por cualquiera de los dos laterales", "por la parte delantera y siempre a expensas de que el piloto o la tripulación lo autorice", "por la parte delantera o por cualquiera de los laterales y siempre a expensas de que el piloto o la tripulación lo autorice", "por la parte delantera"], "correct": 1, "sourceNumber": 23, "block": "seguridad", "page": 47, "explanation": "La aproximación que exige este test es por delante y solo cuando el piloto o la tripulación la autoricen. La autorización y permanecer visible son parte de la respuesta; no basta con nombrar una dirección.", "contrast": "La opción «por la parte delantera» es incompleta porque omite el permiso. La que añade cualquiera de los laterales introduce una libertad de aproximación que no concede el protocolo estudiado."}, {"id": "academia-forestales-2-24", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El riesgo anual de incendios se define como:", "options": ["el número de incendios por cada 10.000 ha forestales", "la probabilidad de número de incendios en cada zona", "el número de ha quemadas cada año", "la estadística anual de incendios en cada zona"], "correct": 0, "sourceNumber": 24, "block": "peligro", "page": 52, "explanation": "El indicador de riesgo anual de los apuntes se define como número de incendios por cada 10.000 ha forestales. Relaciona una frecuencia de incendios con una superficie de referencia, no con las hectáreas que hayan ardido.", "contrast": "La gravedad anual se expresa como porcentaje de superficie forestal quemada en el año. Riesgo anual → número de incendios; gravedad anual → proporción de superficie quemada."}, {"id": "academia-forestales-2-25", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "¿Qué es el fuego prescrito?", "options": ["un incendio forestal que se escapa del ataque ampliado", "una quema de ensanche", "un tipo de contrafuego", "una quema controlada"], "correct": 3, "sourceNumber": 25, "block": "tecnicas", "page": 52, "explanation": "Entre las opciones, quema controlada es la que corresponde al fuego prescrito. El concepto completo es una ignición planificada, sujeta a condiciones definidas y dirigida a objetivos concretos, como reducir acumulaciones de combustible.", "contrast": "Un contrafuego o una quema de ensanche persiguen objetivos específicos del combate. Un incendio que escapa al ataque ampliado no es por ello un fuego prescrito.", "review": {"title": "La clave breve y la definición completa", "text": "«Quema controlada» es la opción correcta del test, pero el término prescrito añade planificación, condiciones y objetivos. La definición de NWCG también exige ignición planificada conforme a las normas aplicables para alcanzar objetivos específicos.", "links": [{"title": "NWCG · Definición de fuego prescrito", "url": "https://www.nwcg.gov/publications/pms205/nwcg-glossary-of-wildland-fire-pms-205/prescribed-fire-982"}]}}, {"id": "academia-forestales-2-26", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "El factor topográfico más importante en el comportamiento del fuego es:", "options": ["la exposición de la ladera", "la configuración", "la pendiente", "el relieve"], "correct": 2, "sourceNumber": 26, "block": "topografia", "page": 16, "explanation": "La pendiente es el factor topográfico que el temario destaca como más importante. Ladera arriba acerca el combustible a las llamas y favorece la transmisión de calor por radiación y convección, aumentando el precalentamiento.", "contrast": "Exposición y configuración también influyen, pero no son el factor que el texto califica de mayor importancia en esta pregunta."}, {"id": "academia-forestales-2-27", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Especies moderadamente o poco inflamables:", "options": ["madroño, cedro y alcornoque", "enebro, cedro y romero", "encina, tojo y tomillo", "madroño, enebro y cedro"], "correct": 3, "sourceNumber": 27, "block": "magnitudes", "page": 15, "explanation": "El grupo que el material clasifica como de inflamabilidad moderada o poca es madroño, enebro y cedro. La única opción que mantiene esos tres miembros es la última.", "contrast": "El alcornoque y el romero figuran entre los muy inflamables en verano; encina y tomillo, entre los muy inflamables todo el año. Cambiar una especie de grupo hace incorrecto el distractor."}, {"id": "academia-forestales-2-28", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "La humedad de los combustibles vegetales puede variar entre:", "options": ["0-300%", "0-100%", "1-100%", "1-200%"], "correct": 0, "sourceNumber": 28, "block": "combustibles", "page": 13, "extraPages": [15], "explanation": "La academia utiliza 0–300 % como intervalo de referencia. La humedad del combustible se calcula respecto al peso seco, por lo que puede superar el 100 %: 100 g de materia seca y 200 g de agua equivalen a 200 % de humedad en base seca.", "contrast": "No es humedad relativa del aire, cuyo porcentaje compara vapor presente con saturación. Los apuntes hablan incluso de más del 300 %: el intervalo del test es orientativo, no un máximo físico absoluto."}, {"id": "academia-forestales-2-29", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "La capacidad del combustible para entrar en ignición se llama:", "options": ["combustibilidad", "consumibilidad", "sostenibilidad", "ignitabilidad"], "correct": 3, "sourceNumber": 29, "block": "bases", "page": 6, "explanation": "Ignitabilidad es la capacidad del combustible para iniciar la combustión ante una fuente de calor suficiente. La pregunta que la identifica es «¿puede entrar en ignición?».", "contrast": "Sostenibilidad → mantener la combustión; combustibilidad → velocidad de quema; consumibilidad → capacidad para consumirse. No confundas comenzar con continuar."}, {"id": "academia-forestales-2-30", "origin": "academia", "test": "academia-2", "sourceTest": "Incendios forestales 2", "sourceLabel": "Academia · Forestales 2", "q": "Disminuyen el diámetro de las gotas de agua y provocan una mayor penetración:", "options": ["retardantes", "humectantes", "viscosantes", "espuma"], "correct": 1, "sourceNumber": 30, "block": "tecnicas", "page": 52, "explanation": "La clave es humectantes. El material los vincula a una mayor penetración y lo expresa como reducción del diámetro de las gotas. Su efecto humectante se entiende por la reducción de la tensión superficial del agua, facilitando el mojado del combustible.", "contrast": "Los retardantes del cuadro se relacionan con mayor viscosidad y menor escurrimiento. No intercambies penetración con retención del producto sobre el combustible."}, {"id": "academia-forestales-3-01", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "La interfaz urbano forestal es una zona que incluye tanto edificaciones dentro o próximas a espacios de vegetación forestal. Esta interacción representa un escenario diferenciado respecto al riesgo de incendio que se conoce como incendios de:", "options": ["segunda generación", "tercera generación", "cuarta generación", "quinta generación"], "correct": 2, "sourceNumber": 1, "block": "prediccion", "page": 53, "explanation": "La cuarta generación incorpora la interfaz urbano-forestal: edificaciones y vegetación forestal entran en contacto y el incendio puede comprometer simultáneamente el monte y las viviendas. Esa interacción es la pista que pide el enunciado.", "contrast": "Segunda → rapidez; tercera → copas y convección; cuarta → interfaz; quinta → simultaneidad de grandes incendios. Tu imagen mental: la Oca (4) mete un bosque dentro de una ciudad."}, {"id": "academia-forestales-3-02", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Según la superficie afectada, un conato afecta a superficies:", "options": ["inferiores a 2 ha", "inferiores a 1 ha", "inferiores a 1,5 ha", "inferiores a 2,5 ha"], "correct": 1, "sourceNumber": 2, "block": "peligro", "page": null, "explanation": "El umbral de este test es menos de 1 ha de superficie afectada. Por ejemplo, 0,8 ha corresponde a un conato; 1 ha exacta ya no satisface la expresión «inferior a 1 ha». Una hectárea equivale a 10.000 m².", "contrast": "Fíjate en el signo: conato < 1 ha. No lo confundas con los cientos de hectáreas que se usan para identificar un gran incendio forestal."}, {"id": "academia-forestales-3-03", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Según la superficie afectada, un gran incendio forestal afecta a superficies:", "options": ["superiores o iguales a 50 ha", "superiores o iguales a 500 ha", "superiores o iguales a 100 ha", "superiores o iguales a 10 ha"], "correct": 1, "sourceNumber": 3, "block": "peligro", "page": 52, "explanation": "La academia marca superficie superior o igual a 500 ha. El número que discrimina entre las opciones es 500, frente a 50, 100 y 10. Conviene conservar también el matiz del límite, porque el test escribe ≥ 500 ha y los apuntes utilizan > 500 ha.", "contrast": "Conato → menos de 1 ha; GIF → referencia de 500 ha. La superficie afectada no indica por sí sola la duración, intensidad o dificultad de extinción.", "review": {"title": "500 ha: atención al signo del umbral", "text": "Se puntúa con ≥ 500 ha porque es la clave compartida. La p. 52 de los apuntes y el informe actual de MITECO hablan de superar 500 ha. No conviertas el «igual» del test en una definición universal; si se pregunta por el límite exacto, sigue la fuente indicada.", "links": [{"title": "MITECO · Definición de GIF en el informe de incendios", "url": "https://www.miteco.gob.es/content/dam/miteco/es/biodiversidad/temas/incendios-forestales/estimacion_provisional.html"}]}}, {"id": "academia-forestales-3-04", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Los fuegos de subsuelo se suelen dar en zonas de:", "options": ["gayuba", "brezo", "musgo", "hojarasca bajo arbolado"], "correct": 0, "sourceNumber": 4, "block": "tipos", "page": 8, "explanation": "La respuesta señalada por la academia es gayuba. El concepto que sí explica el temario es fuego de subsuelo: se propaga por la materia orgánica situada bajo la superficie, puede permanecer poco visible y durar días o semanas; se cita la turba como ejemplo.", "contrast": "El estrato donde arde es lo que define el tipo de fuego. La hojarasca situada sobre el suelo se relaciona con superficie; el nombre de una especie, por sí solo, no demuestra una combustión subterránea.", "review": {"title": "Asociación específica del test: gayuba", "text": "La página de subsuelo no menciona gayuba ni compara estas cuatro opciones. Se conserva la clave de academia, pero no se presenta como una preferencia botánica demostrada por los apuntes. Para comprenderlo, recuerda materia orgánica bajo la superficie; para este test concreto, gayuba."}}, {"id": "academia-forestales-3-05", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Cuando el fuego avanza por las copas de los árboles acoplado a un fuego de superficie y no independiente de él, se conoce como:", "options": ["antorcheo", "copas activo", "copas pasivo", "lineal"], "correct": 2, "sourceNumber": 5, "block": "tipos", "page": 10, "extraPages": [9], "explanation": "Copas pasivo es la clave en la clasificación de CEIS / Arkaute que sigue esta pregunta. El fuego de las copas avanza acoplado al de superficie: depende de él para mantener la propagación. La pista decisiva es «acoplado» y «no independiente».", "contrast": "En esa misma clasificación, antorcheo afecta de forma intermitente a árboles aislados y copas activo avanza de manera independiente del fuego superficial.", "review": {"title": "El nombre cambia según el manual", "text": "Ricardo Vélez llama copas activo al avance acoplado y copas independiente al que se separa del de superficie. CEIS / Arkaute usa pasivo para el acoplado y activo para el independiente. El comportamiento es la referencia común; no memorices el nombre sin su clasificación."}}, {"id": "academia-forestales-3-06", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "El área de un incendio forestal que no se ha quemado entre el incendio principal y cualquiera de los dedos se denomina:", "options": ["lengua", "isla", "golfo", "bolsa"], "correct": 3, "sourceNumber": 6, "block": "anatomia", "page": 7, "explanation": "La bolsa o entrante es una zona de combustible sin quemar que penetra entre el cuerpo principal del incendio y uno de sus dedos o lenguas. Es una concavidad del perímetro, tal como muestra el dibujo de las partes del incendio.", "contrast": "Dedo o lengua → saliente de fuego. Bolsa o entrante → hueco sin quemar entre salientes. Isla → combustible sin quemar rodeado por el área quemada; no es simplemente cualquier entrante."}, {"id": "academia-forestales-3-07", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "En el desarrollo de incendios forestales es frecuente la proyección a distancia del frente del fuego de partículas vegetales incandescentes o inflamadas, las cuales se denominan:", "options": ["brasas", "chispas", "pavesas", "testas"], "correct": 2, "sourceNumber": 7, "block": "anatomia", "page": 18, "explanation": "Pavesas es el nombre de las partículas vegetales incandescentes o inflamadas que pueden ser transportadas a distancia por el aire. Al caer sobre combustible receptivo por delante del frente pueden originar focos secundarios separados del incendio principal.", "contrast": "La pregunta incluye la proyección y el transporte a distancia: esa es la pista para elegir pavesas frente a términos generales como brasas o chispas."}, {"id": "academia-forestales-3-08", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "La cantidad de vapor de agua por unidad de volumen de aire ambiente es:", "options": ["humedad relativa", "humedad absoluta", "punto de rocío", "punto de saturación"], "correct": 1, "sourceNumber": 8, "block": "meteorologia", "page": 20, "explanation": "La humedad absoluta expresa la masa de vapor de agua por unidad de volumen de aire, normalmente en g/m³. Por ejemplo, 8 g de vapor en 1 m³ de aire representan una humedad absoluta de 8 g/m³.", "contrast": "Relativa → comparación con la saturación a igual temperatura, en %. Punto de rocío → temperatura a la que se alcanza la saturación al enfriar. Absoluta → masa de vapor por volumen."}, {"id": "academia-forestales-3-09", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "El viento se mueve por las diferencias de temperatura, diferencias de presión, rotación de la tierra y por:", "options": ["efecto Fourier", "efecto Eolos", "fuerza Coriolis", "fuerza Windtrasser"], "correct": 2, "sourceNumber": 9, "block": "meteorologia", "page": null, "explanation": "La clave es fuerza de Coriolis, que interviene desviando la trayectoria del aire en movimiento en el sistema de referencia terrestre. Está vinculada a la rotación de la Tierra; el gradiente de presión impulsa el movimiento del aire.", "contrast": "Las diferencias térmicas contribuyen a crear diferencias de presión. Coriolis desvía el movimiento: no es otra causa independiente de la rotación terrestre.", "review": {"title": "El enunciado enumera dos veces una misma relación", "text": "La pregunta separa «rotación de la Tierra» y «Coriolis», pero el efecto Coriolis deriva de esa rotación. AEMET explica que curva la trayectoria del viento. Elige Coriolis entre estas opciones conservando esa relación física.", "links": [{"title": "AEMET · Viento y efecto Coriolis", "url": "https://aemetblog.es/2017/08/05/estimacion-instantanea-del-tiempo-regla-de-los-vientos-cruzados/"}]}}, {"id": "academia-forestales-3-10", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "1 nudo equivale a:", "options": ["1,523 Km/h", "1,852 Km/h", "2,183 Km/h", "2,217 Km/h"], "correct": 1, "sourceNumber": 10, "block": "meteorologia", "page": null, "explanation": "1 nudo equivale exactamente a 1,852 km/h: es una milla náutica, de 1.852 metros, recorrida en una hora. Para pasar de nudos a km/h multiplica por 1,852; por ejemplo, 10 nudos son 18,52 km/h.", "contrast": "Imagen mental con tu casillero: una Tea (1) hace un NUDO en un Chal (85) que arrastra a Noé (2). Recupera 1 | 85 | 2 → 1,852 y añade km/h. La coma va después del 1; no son 1.852 km/h."}, {"id": "academia-forestales-3-11", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Un viento de 270º proviene del:", "options": ["este", "suroeste", "sureste", "oeste"], "correct": 3, "sourceNumber": 11, "block": "meteorologia", "page": 18, "explanation": "Un viento de 270° procede del oeste. La dirección meteorológica indica de dónde viene el viento y se mide desde el norte en sentido horario: 0° o 360° norte, 90° este, 180° sur y 270° oeste.", "contrast": "No confundas procedencia con destino: un viento del oeste se dirige hacia el este. Suroeste corresponde a 225° y sureste a 135°."}, {"id": "academia-forestales-3-12", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Vientos muy cálidos, secos y de gran intensidad que soplan desde regiones altas hacia las bajas y su velocidad y características desecantes sobre la vegetación pueden tener como consecuencia que los incendios forestales sean realmente incontrolables son:", "options": ["Olas de montaña", "vientos de valle", "inversión térmica", "Foehn"], "correct": 3, "sourceNumber": 12, "block": "meteorologia", "page": 18, "explanation": "La descripción corresponde al Foehn: viento descendente cálido y seco a sotavento de una montaña. Al descender, el aire se comprime y aumenta su temperatura; ese ambiente puede favorecer la desecación del combustible y agravar la propagación.", "contrast": "La inversión térmica es una distribución de temperatura con la altura, no el nombre de este viento. La pista conjunta es descenso desde zonas altas + calentamiento + sequedad."}, {"id": "academia-forestales-3-13", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Una inversión térmica donde la temperatura aumenta con la altura porque las capas de aire a nivel medio, vinculado a un anticiclón, se hunden progresivamente y se calientan por compresión al caer desde lo alto, con el resultado de una capa de aire caliente, seco y muy estable, que se puede prolongar durante días se denomina:", "options": ["inversión por subsidencia", "inversión de radiación", "inversión frontal", "inversión marina"], "correct": 0, "sourceNumber": 13, "block": "meteorologia", "page": null, "explanation": "Es una inversión por subsidencia: el aire desciende en un entorno anticiclónico, se comprime y se calienta, formando una capa cálida y estable por encima de aire más frío. El hundimiento de aire de niveles medios es la pista decisiva.", "contrast": "La inversión de radiación nace del enfriamiento del suelo, normalmente nocturno. Aquí se describe calentamiento del aire al descender, no enfriamiento de la superficie.", "review": {"title": "Subsidencia y radiación: dos mecanismos distintos", "text": "AEMET distingue la inversión de subsidencia, asociada al descenso de aire en anticiclones, de la que se forma por enfriamiento nocturno cerca del suelo. La foto de inversión del temario se centra en el valle; no sirve por sí sola como desarrollo de esta definición más específica.", "links": [{"title": "AEMET · Tipos de inversión térmica", "url": "https://aemetblog.es/2020/10/04/ya-conoces-nuestro-meteoglosario-visual/"}]}}, {"id": "academia-forestales-3-14", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "A la tormenta de fuego se la conoce también como:", "options": ["tormenta cálida", "tormenta pyrea", "tormenta de convección", "tormenta ígnea"], "correct": 3, "sourceNumber": 14, "block": "prediccion", "page": null, "explanation": "Tormenta ígnea es el sinónimo que marca la academia para tormenta de fuego. «Ígneo» significa relacionado con el fuego. Asocia el término a la intensa interacción entre la combustión y los movimientos de aire generados por su calor.", "contrast": "Aunque la convección participa en ese comportamiento, «tormenta de convección» no es el sinónimo que solicita este test. La pregunta busca el nombre equivalente, no un mecanismo de transferencia de calor."}, {"id": "academia-forestales-3-15", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Las nubes que acompañan incendios o actividades volcánicas y que se producen por un gran calentamiento del aire desde el propio incendio se conocen como:", "options": ["cumulus", "nimbostratus", "cirrocumulus", "pyrocumulus"], "correct": 3, "sourceNumber": 15, "block": "meteorologia", "page": null, "explanation": "La opción es pyrocumulus, en español pirocúmulos: nubes que se forman por la convección intensa asociada al calor de un incendio o una erupción. El aire asciende y, si alcanza condiciones de condensación, aparece la nube sobre la columna.", "contrast": "No toda columna de humo es una nube. Un pirocúmulo tampoco implica necesariamente una tormenta; un desarrollo mayor puede dar lugar a un pirocumulonimbo.", "review": {"title": "Nube formada por el incendio, no solo humo", "text": "AEMET explica que las nubes flammagenitus, conocidas como pirocúmulos, son nubes auténticas cuya formación depende de la energía y humedad asociadas al fuego. La opción conserva la grafía pyrocumulus del cuestionario.", "links": [{"title": "AEMET · Pirocúmulos y nubes flammagenitus", "url": "https://aemetblog.es/2017/07/28/los-nuevos-tipos-de-nubes-reconocidos-por-la-organizacion-meteorologica-mundial-omm/"}]}}, {"id": "academia-forestales-3-16", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Dentro de las características del combustible vegetal, según su tamaño y forma, un matorral con 35 mm de diámetro se considera:", "options": ["fino", "regular", "mediano", "grueso"], "correct": 2, "sourceNumber": 16, "block": "combustibles", "page": 13, "explanation": "35 mm está dentro del intervalo de 25–75 mm, que el temario clasifica como combustible mediano y relaciona con una retardación de 100 horas. Basta situar el diámetro entre los dos límites de esa categoría.", "contrast": "El diámetro se aplica a la partícula combustible, por ejemplo una rama, no al tamaño completo del matorral. En los apuntes: < 5 mm fino; 5–25 mm ligero; 25–75 mm mediano; > 75 mm grande."}, {"id": "academia-forestales-3-17", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "El tiempo que tarda un combustible muerto en equilibrar su contenido en humedad con la humedad relativa del ambiente se conoce como:", "options": ["tiempo de desecación", "tiempo relativo", "tiempo de balance", "tiempo de retardo"], "correct": 3, "sourceNumber": 17, "block": "combustibles", "page": 13, "explanation": "El nombre buscado es tiempo de retardo o retardación. Describe la rapidez con la que un combustible muerto responde a cambios de humedad ambiental. Cuanto menor es ese tiempo, más deprisa se aproxima su humedad a la de equilibrio.", "contrast": "Una unidad de retardo corresponde aproximadamente al 63 % del cambio necesario hacia el equilibrio, no a alcanzar todo el equilibrio. Tampoco iguala dos porcentajes distintos: humedad del combustible y humedad relativa del aire.", "review": {"title": "La definición del test está abreviada", "text": "El enunciado dice «equilibrar», pero la definición precisa de los apuntes utiliza aproximadamente el 63 % de la diferencia entre humedad inicial y de equilibrio. Recuerda: retardo = velocidad de ajuste; un tiempo de retardo ≠ equilibrio completo."}}, {"id": "academia-forestales-3-18", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Según la escala de Rothermel, los modelos que van del 4 al 7 son:", "options": ["pastos", "matorral", "hojarasca", "restos de corta"], "correct": 1, "sourceNumber": 18, "block": "combustibles", "page": 12, "explanation": "En los trece modelos del esquema de Rothermel, el grupo de matorral comprende los modelos 4, 5, 6 y 7. La pregunta pide el grupo completo, no la descripción particular de uno de sus modelos.", "contrast": "Recupera los intervalos en orden: 1–3 pastos; 4–7 matorral; 8–10 hojarasca bajo arbolado; 11–13 restos de corta y operaciones selvícolas."}, {"id": "academia-forestales-3-19", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Matorrales mayores de 2 metros, pinares con sotobosque de especies inflamables, pertenecen según la escala de Rothermel al modelo:", "options": ["4", "5", "6", "7"], "correct": 3, "sourceNumber": 19, "block": "combustibles", "page": 12, "explanation": "La academia señala el modelo 7 y utiliza como pista los pinares con sotobosque de especies inflamables. La tabla resumida del temario describe el 7 como matorral muy inflamable; sin embargo, el dato aislado de matorral de más de 2 m aparece en el modelo 4.", "contrast": "Modelo 4 → matorral muy denso de más de 2 m. Modelo 5 → denso y verde de menos de 1 m. Modelo 6 → parecido al 5, más alto e inflamable, con restos. Modelo 7 → muy inflamable.", "review": {"title": "Enunciado con pistas de dos modelos", "text": "Se conserva el 7 como clave de este test. No memorices «más de 2 metros = 7»: la p. 12 asigna expresamente el matorral muy denso de esa altura al 4. El test combina la altura con otra descripción; para una pregunta distinta, comprueba la estructura completa del combustible."}}, {"id": "academia-forestales-3-20", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "¿Cuál de las siguientes no es una especie muy inflamable durante casi todo el año?", "options": ["eucalipto", "encina", "romero", "pino rodeno"], "correct": 3, "sourceNumber": 20, "block": "magnitudes", "page": 15, "explanation": "La academia marca pino rodeno como la especie que no pertenece al grupo de muy inflamables durante casi todo el año. En los apuntes, pino pinaster figura en el grupo de verano; eucalipto y encina sí están en el grupo de todo el año.", "contrast": "El romero también aparece en el grupo de verano de la p. 15. Por tanto, esa tabla permite excluir del grupo de todo el año tanto al pino como al romero: la pregunta no tiene una única respuesta compatible con esos apuntes.", "review": {"title": "Dos respuestas posibles al contrastar los apuntes", "text": "La puntuación sigue pino rodeno, la clave recibida. La tabla del temario no respalda que romero sea un distractor incorrecto: también lo coloca en verano. Conserva la clasificación del material y trata esta pregunta como una discrepancia pendiente de aclaración con la academia."}}, {"id": "academia-forestales-3-21", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "¿Cuál de las siguientes no es una especie muy inflamable sólo durante el verano?", "options": ["alcornoque", "madroño", "espliego", "tomillo"], "correct": 1, "sourceNumber": 21, "block": "magnitudes", "page": 15, "explanation": "Madroño es la respuesta marcada: los apuntes lo incluyen, junto con enebro y cedros, entre las especies de inflamabilidad moderada o poca. Por ello no pertenece al grupo de muy inflamables solo en verano.", "contrast": "El alcornoque sí figura en verano. Pero el tomillo aparece en el grupo de todo el año, de modo que tampoco encaja literalmente en «solo durante el verano». El espliego no está en la lista resumida compartida.", "review": {"title": "«Solo en verano» hace ambiguo el descarte", "text": "Se puntúa madroño según la academia. Con el cuadro de la p. 15, tomillo también queda fuera del grupo exclusivo de verano, aunque sea muy inflamable todo el año. La clave del test no basta para cambiar de grupo al tomillo ni para completar una clasificación del espliego."}}, {"id": "academia-forestales-3-22", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "¿Cuál de las siguientes no es una especie medianamente inflamable?", "options": ["frambuesa", "madroño", "enebro", "carrasca"], "correct": 0, "sourceNumber": 22, "block": "magnitudes", "page": 15, "explanation": "La academia señala frambuesa como la especie que no es medianamente inflamable. La tabla de los apuntes sí permite reconocer madroño y enebro en el grupo moderado o poco inflamable, pero no incluye frambuesa entre las especies enumeradas.", "contrast": "Carrasca es un nombre común de la encina, que el material sitúa entre las muy inflamables todo el año. Por ello tampoco puede justificarse, con esa tabla, que carrasca sea una opción medianamente inflamable.", "review": {"title": "La clave no resuelve la opción «carrasca»", "text": "Se conserva frambuesa para la corrección del cuestionario. La guía botánica del Ayuntamiento de Zaragoza identifica encina y carrasca como nombres de Quercus ilex. Al compararlo con la p. 15 aparece otra exclusión posible; no deduzcas una clasificación universal de frambuesa a partir de esta pregunta.", "links": [{"title": "Ayuntamiento de Zaragoza · Encina / carrasca", "url": "https://www.zaragoza.es/sede/portal/medioambiente/infraestructura-verde/parques-jardines/especies/servicio/especie/66"}]}}, {"id": "academia-forestales-3-23", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Un humo de color gris café procede de la quema de:", "options": ["matorrales densos", "combustible húmedo", "arbustos ralos", "encinares"], "correct": 2, "sourceNumber": 23, "block": "combustibles", "page": null, "explanation": "Arbustos ralos es la asociación que utiliza este test para humo gris café. La corrección compartida permite conocer la clave de academia, pero el resumen fotografiado no aporta una tabla que justifique ese emparejamiento entre color y vegetación.", "contrast": "Úsalo como asociación de este cuestionario. Un color de humo aislado no permite identificar de manera inequívoca una especie o formación vegetal.", "review": {"title": "Color del humo: clave del cuestionario", "text": "No se ha localizado esta equivalencia en las páginas del temario. Se conserva gris café → arbustos ralos como respuesta de academia, sin convertirla en una regla general de identificación del combustible."}}, {"id": "academia-forestales-3-24", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Un humo de color gris negro procede de la quema de:", "options": ["pinares", "pastizales", "combustibles secos", "arbustos ralos"], "correct": 0, "sourceNumber": 24, "block": "combustibles", "page": null, "explanation": "Pinares es la respuesta que marca este tercer test para el humo gris negro. Memoriza el emparejamiento únicamente como clave del cuestionario: la corrección recibida no demuestra que todo pinar produzca humo de ese color.", "contrast": "En Forestales 2, la pregunta 7 asociaba los pinares a humo amarillo. Ambos test usan asociaciones diferentes, por lo que no ofrecen una correspondencia única entre pinares y color.", "review": {"title": "Diferencia con Forestales 2 · pregunta 7", "text": "Forestales 2: pinares → amarillo. Forestales 3: gris negro → pinares. Se mantienen las claves recibidas para practicar cada test, pero no se unifican en una regla física. Los apuntes compartidos no incluyen una tabla que resuelva estas asociaciones."}}, {"id": "academia-forestales-3-25", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "El factor topográfico más importante en el comportamiento del fuego es:", "options": ["la pendiente", "la exposición", "la configuración", "todos son igual de importantes"], "correct": 0, "sourceNumber": 25, "block": "topografia", "page": 16, "explanation": "La pendiente es el factor topográfico que el temario destaca como más importante. Al avanzar ladera arriba, las llamas quedan más cerca del combustible situado por delante y favorecen su precalentamiento por radiación y convección.", "contrast": "Exposición y configuración también afectan al comportamiento, pero el texto no les atribuye la misma importancia en esta comparación. Pendiente → inclinación; exposición → orientación de la ladera."}, {"id": "academia-forestales-3-26", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "El mecanismo de transmisión de calor que contribuye con más eficacia en un incendio forestal es el de:", "options": ["conducción", "radiación", "convección", "ninguna es correcta"], "correct": 2, "sourceNumber": 26, "block": "bases", "page": 6, "explanation": "La academia elige convección: el calor se transmite mediante el movimiento de aire y gases calientes. Las corrientes ascendentes y el transporte de energía hacia otros combustibles explican su importancia en el comportamiento de un incendio forestal.", "contrast": "Conducción → transferencia a través de la materia sin transporte global de ella. Radiación → energía transmitida por ondas. Convección → transporte por movimiento del fluido.", "review": {"title": "La eficacia depende de las condiciones", "text": "Convección es la clave de este test. La pregunta no fija viento, pendiente, disposición del combustible ni zona del incendio; por ello no demuestra que este mecanismo domine siempre. Los apuntes explican también el papel de la radiación en el precalentamiento."}}, {"id": "academia-forestales-3-27", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "Al área de combustible vegetal que no se ha quemado dentro del perímetro del incendio se le conoce como:", "options": ["bolsa", "isla", "burbuja", "entrante"], "correct": 1, "sourceNumber": 27, "block": "anatomia", "page": 7, "explanation": "Una isla es una porción de combustible que queda sin quemar dentro del área afectada, rodeada por terreno quemado. La imagen útil es un islote de vegetación que permanece intacto en medio de la superficie recorrida por el incendio.", "contrast": "La bolsa o entrante se introduce desde el borde entre dedos o lenguas. Para distinguirlas, pregunta si la zona está rodeada por lo quemado (isla) o si forma una concavidad abierta del perímetro (bolsa)."}, {"id": "academia-forestales-3-28", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "El fuego que avanza por las copas de los árboles independientemente de lo que ocurre en la superficie se conoce como:", "options": ["copas pasivo", "copas activo", "antorcheo", "copas independiente"], "correct": 1, "sourceNumber": 28, "block": "tipos", "page": 10, "extraPages": [9, 33], "explanation": "Copas activo es la clave de la clasificación CEIS / Arkaute seguida por este test: el frente avanza por las copas independientemente de lo que ocurre en superficie. Contrástalo con la pregunta 5 de este mismo test: acoplado = pasivo.", "contrast": "Antorcheo es la inflamación intermitente de árboles aislados. La opción copas independiente describe el comportamiento y es el nombre utilizado por Vélez, pero la academia puntúa aquí copas activo.", "review": {"title": "«Activo» e «independiente» según la clasificación", "text": "El enunciado no nombra manual y ofrece dos términos que se usan para este comportamiento en fuentes distintas. CEIS / Arkaute: activo; Vélez: independiente. Se respeta la clave de academia, con esta aclaración para evitar trasladarla a cualquier clasificación."}}, {"id": "academia-forestales-3-29", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "No tienen la consideración de incendio forestal los que afecten a:", "options": ["terrenos yermos, roquedos y arenales", "construcciones e infraestructuras destinadas al servicio del monte en el que se ubican", "terrenos agrícolas abandonados", "todos son incendios forestales"], "correct": 3, "sourceNumber": 29, "block": "bases", "page": null, "explanation": "La academia marca «todos son incendios forestales». La intención del ejercicio es reconocer categorías incluidas en el concepto legal de monte: terrenos yermos, roquedos y arenales, infraestructuras a su servicio y determinados terrenos agrícolas abandonados.", "contrast": "Monte e incendio forestal son conceptos distintos. Que un lugar tenga consideración de monte no convierte cualquier fuego que lo afecte en forestal; importan el combustible y la propagación sin control.", "review": {"title": "La ley exige condiciones que el test omite", "text": "El artículo 5 de la Ley 43/2003 exige que el terreno agrícola abandonado cumpla condiciones y plazos autonómicos y muestre signos inequívocos de estado forestal. El artículo 6.k vincula incendio forestal a fuego sin control sobre combustibles forestales en el monte. La clave de academia simplifica estos requisitos.", "links": [{"title": "BOE · Ley de Montes, artículo 5", "url": "https://www.boe.es/buscar/act.php?id=BOE-A-2003-21339#a5"}, {"title": "BOE · Definición de incendio forestal, artículo 6", "url": "https://www.boe.es/buscar/act.php?id=BOE-A-2003-21339#a6"}]}}, {"id": "academia-forestales-3-30", "origin": "academia", "test": "academia-3", "sourceTest": "Incendios forestales 3", "sourceLabel": "Academia · Forestales 3", "q": "La cola del incendio se suele ubicar en:", "options": ["donde comenzamos a trabajar", "el origen del incendio", "en los focos secundarios", "en el punto de anclaje"], "correct": 1, "sourceNumber": 30, "block": "anatomia", "page": 7, "explanation": "La cola suele situarse cerca del origen del incendio: es su parte posterior, opuesta a la dirección de avance principal de la cabeza. La palabra «suele» importa, porque la forma y la dirección del avance pueden cambiar con el viento y el terreno.", "contrast": "Un punto de anclaje es una referencia elegida para iniciar o asegurar trabajos de extinción; no define por sí solo la cola. Los focos secundarios están separados del incendio principal."}];
