const sourceRanges={bases:[5,7,11],anatomia:[7,8],tipos:[8,10,33,34],combustibles:[11,13,15],magnitudes:[14,15],topografia:[15,16,33],meteorologia:[17,20],tecnicas:[21,22,52],metodos:[25,28,31],lineas:[21,21,29,31],organizacion:[23,24,32],peligro:[32,34,52],herramientas:[35,38],maquinaria:[39,45],seguridad:[46,52],prediccion:[53,55]};
blocks.forEach(b=>{const vals=sourceRanges[b.id];const pageSet=new Set();for(let i=0;i<vals.length;i+=2){if(i+1<vals.length){for(let p=vals[i];p<=vals[i+1];p++)pageSet.add(p)}else pageSet.add(vals[i])}const d=document.createElement('details');d.className='extra sourcelinks';d.innerHTML='<summary>Consultar las páginas de este bloque</summary><div class="sourcegrid">'+[...pageSet].sort((a,b)=>a-b).map(p=>`<button data-image="forestales-assets/page-${String(p-1).padStart(2,'0')}.jpg" data-caption="Temario · p. ${p} · ${pagetitles[p-2]}">p. ${p} · ${pagetitles[p-2]}</button>`).join('')+'</div>';b.insertBefore(d,b.querySelector('.done'))});
document.querySelector('#quickgrid').innerHTML=blocks.map((b,i)=>`<div class="quickcard"><div class="overline">${String(i+1).padStart(2,'0')}</div><h3>${b.dataset.title}</h3><p>${b.querySelector('.essential').innerHTML.replace(/<div class="overline">.*?<\/div>/,'')}</p><a href="#${b.id}">Revisar el bloque →</a></div>`).join('');
