function renderPegs(){const q=normalize(document.querySelector('#pegsearch').value.trim());const matches=pegs.map((label,n)=>({label,n})).filter(p=>!q||normalize(p.n+' '+p.label).includes(q));document.querySelector('#peglist').innerHTML=matches.length?matches.map(p=>`<div class="peg"><b>${p.n}</b>${p.label}</div>`).join(''):'<p class="note">No hay casillas con ese término.</p>'}document.querySelector('#pegsearch').addEventListener('input',renderPegs);renderPegs();
document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>{b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');const n=document.querySelectorAll('[data-align][aria-pressed=true]').length;document.querySelector('#alignresult').textContent=`${n}/3 · ${['Fuera de alineación','Poca alineación','Media alineación','Plena alineación'][n]}`});
imagegroups.forEach((g,i)=>document.querySelector('#imagetopic').insertAdjacentHTML('beforeend',`<option value="${i}">${g[0]}</option>`));
function renderGallery(){const selected=document.querySelector('#imagetopic').value;const range=selected==='all'?[1,54]:imagegroups[Number(selected)].slice(1);document.querySelector('#gallery').innerHTML=pagetitles.map((title,i)=>({title,n:i+1})).filter(p=>p.n>=range[0]&&p.n<=range[1]).map(p=>`<button data-image="forestales-assets/page-${String(p.n).padStart(2,'0')}.jpg" data-caption="Temario · p. ${p.n+1} · ${p.title}" aria-label="Ampliar página ${p.n+1}: ${p.title}"><img loading="lazy" src="forestales-assets/thumb-${String(p.n).padStart(2,'0')}.jpg" alt=""><span><b>p. ${p.n+1}</b> · ${p.title}</span></button>`).join('')}document.querySelector('#imagetopic').onchange=renderGallery;renderGallery();
let cardState=state.get('cards-v1',{});let deck=[],position=0,revealed=false;
function cardPool(){const type=document.querySelector('#deck').value;const topic=document.querySelector('#cardtopic').value;return flashcards.filter(c=>{const s=cardState[c.id];return(topic==='all'||c.block===topic)&&(type==='all'||(type==='repeat'&&s?.repeat)||(type==='due'&&(!s?.due||s.due<=Date.now())))})}
function renderCard(status=''){revealed=false;const c=deck[position];document.querySelector('#flasha').hidden=true;document.querySelector('#again').disabled=true;document.querySelector('#remember').disabled=true;document.querySelector('#flashstatus').textContent=status;const nDue=flashcards.filter(c=>!cardState[c.id]?.due||cardState[c.id].due<=Date.now()).length;document.querySelector('#flashcount').textContent=c?`Tarjeta ${position+1} de ${deck.length} · ${nDue} pendientes hoy en total`:`Mazo vacío · ${nDue} pendientes hoy en total`;document.querySelector('#flashtag').textContent=c?topicName(c.block)+' · p. '+c.page:'Sin tarjetas pendientes';document.querySelector('#flashq').textContent=c?c.q:'Has completado este mazo. Puedes practicar todas las tarjetas o cambiar de bloque.';document.querySelector('#reveal').disabled=!c;document.querySelector('#prev').disabled=!c;document.querySelector('#next').disabled=!c;document.querySelector('#flasha').innerHTML=c?`<p>${c.a}</p><a href="#${c.block}">Revisar el bloque →</a> <button data-image="forestales-assets/page-${String(c.page-1).padStart(2,'0')}.jpg" data-caption="Temario · p. ${c.page}">Ver fuente</button>`:'';document.querySelector('#flashimage')?.remove();if(c?.image){const img=document.createElement('img');img.id='flashimage';img.src=`forestales-assets/${c.image}.jpg`;img.alt='Dibujo del temario para esta pregunta';img.style.cssText='max-width:100%;max-height:190px;object-fit:contain;background:#e8e9df;border-radius:6px;margin:0 0 18px';document.querySelector('#flashq').after(img)}}
function rebuildDeck(){deck=cardPool();position=0;renderCard()}
document.querySelector('#deck').onchange=rebuildDeck;document.querySelector('#cardtopic').onchange=rebuildDeck;document.querySelector('#shuffle').onclick=()=>{deck=cardPool();for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}position=0;renderCard()};
function revealCard(){if(!deck.length)return;revealed=true;document.querySelector('#flasha').hidden=false;document.querySelector('#again').disabled=false;document.querySelector('#remember').disabled=false;document.querySelector('#reveal').hidden=true;document.querySelector('#flasha').focus()}
const originalRenderCard=renderCard;renderCard=function(status=''){document.querySelector('#reveal').hidden=false;originalRenderCard(status)};
document.querySelector('#reveal').onclick=revealCard;
function moveCard(delta){if(!deck.length)return;position=(position+delta+deck.length)%deck.length;renderCard()}document.querySelector('#prev').onclick=()=>moveCard(-1);document.querySelector('#next').onclick=()=>moveCard(1);
function gradeCard(remember){if(!revealed||!deck.length)return;const c=deck[position];const previous=cardState[c.id]||{};let label;if(remember){const level=Math.min((previous.level||0)+1,4);const days=[1,3,7,14][level-1];const due=Date.now()+days*86400000;cardState[c.id]={level,due,repeat:false};label=`Guardada. Próximo repaso: ${new Intl.DateTimeFormat('es-ES',{timeZone:'Europe/Madrid',day:'numeric',month:'long'}).format(due)} (en ${days} ${days===1?'día':'días'}).`}else{cardState[c.id]={level:0,due:Date.now(),repeat:true};label='Guardada para repetir hoy. También está en el mazo «Para repetir».'}state.set('cards-v1',cardState);const oldPos=position;const nextPool=cardPool();const ids=new Set(nextPool.map(x=>x.id));deck=deck.filter(x=>ids.has(x.id));const idx=deck.findIndex(x=>x.id===c.id);position=idx>=0?(idx+1)%deck.length:Math.min(oldPos,Math.max(deck.length-1,0));renderCard(label)}document.querySelector('#again').onclick=()=>gradeCard(false);document.querySelector('#remember').onclick=()=>gradeCard(true);rebuildDeck();
document.addEventListener('keydown',e=>{if(currentView!=='flash'||viewer.open||e.target.matches('input,select,textarea,button,a'))return;if(e.key===' '){e.preventDefault();if(!revealed)revealCard()}if(e.key==='ArrowRight'){e.preventDefault();moveCard(1)}if(e.key==='ArrowLeft'){e.preventDefault();moveCard(-1)}});
let quizAnswers={};
const quizEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function quizPool(){const topic=document.querySelector('#quiztopic').value;const source=document.querySelector('#quizsource').value;return quizdata.map((q,i)=>({q,i})).filter(({q})=>(topic==='all'||q.block===topic)&&(source==='all'||(q.origin||'apuntes')===source||q.test===source))}
function updateScore(){const visible=quizPool();const answered=visible.filter(x=>Object.hasOwn(quizAnswers,x.i));const correct=answered.filter(x=>quizAnswers[x.i]===x.q.correct);document.querySelector('#score').textContent=`${correct.length} ${correct.length===1?'acierto':'aciertos'} · ${answered.length}/${visible.length} respondidas`}
function renderQuiz(){const visible=quizPool();document.querySelector('#quizlist').innerHTML=visible.length?visible.map(({q,i})=>`<article class="quizitem" data-question="${i}"${q.id?` id="quiz-${quizEscape(q.id)}"`:''}><div class="quizmeta"><div class="overline">${q.origin==='academia'?quizEscape(q.sourceLabel)+' · '+q.sourceNumber:'Cuaderno · '+(i+1)} · ${quizEscape(topicName(q.block))}</div>${q.review?'<span class="quizbadge">Con aclaración en la corrección</span>':''}</div><h3>${quizEscape(q.q)}</h3><div class="options">${q.options.map((o,j)=>`<button data-answer="${j}"><span aria-hidden="true">${String.fromCharCode(65+j)} · </span>${quizEscape(o)}</button>`).join('')}</div><div class="feedback" hidden role="status"></div></article>`).join(''):'<p class="empty" role="status">Este test no contiene preguntas de ese bloque. Cambia el test o selecciona «Todo el tema».</p>';Object.entries(quizAnswers).forEach(([i,answer])=>displayAnswer(Number(i),answer));document.querySelector('#quizscope').hidden=document.querySelector('#quizsource').value==='apuntes';updateScore()}
function displayAnswer(i,answer){const row=document.querySelector(`[data-question="${i}"]`);if(!row)return;const q=quizdata[i];const correct=answer===q.correct;row.querySelectorAll('[data-answer]').forEach(b=>{const n=Number(b.dataset.answer);b.disabled=true;b.classList.toggle('correct',n===q.correct);b.classList.toggle('wrong',n===answer&&!correct);b.setAttribute('aria-label',q.options[n]+(n===q.correct?' · Respuesta correcta':n===answer?' · Tu respuesta incorrecta':''))});const feedback=row.querySelector('.feedback');feedback.hidden=false;feedback.classList.toggle('error',!correct);const pageLinks=[...new Set([q.page,...(q.extraPages||[])])].filter(p=>Number.isInteger(p)&&p>=2&&p<=55).map(p=>`<button data-image="forestales-assets/page-${String(p-1).padStart(2,'0')}.jpg" data-caption="Temario · p. ${p}">p. ${p}</button>`).join('');const review=q.review?`<details class="quizreview"><summary>${quizEscape(q.review.title)}</summary><p>${quizEscape(q.review.text)}</p>${q.review.links?.length?`<ul>${q.review.links.map(link=>`<li><a href="${quizEscape(link.url)}" target="_blank" rel="noopener noreferrer">${quizEscape(link.title)} ↗</a></li>`).join('')}</ul>`:''}</details>`:'';feedback.innerHTML=`<p><b>${correct?'Correcto.':'Revisa: '+quizEscape(q.options[q.correct])+'.'}</b> ${quizEscape(q.explanation)}</p>${q.contrast?`<p><b>Para distinguirlo.</b> ${quizEscape(q.contrast)}</p>`:''}${review}<div class="quizlinks"><a href="#${q.block}">${q.origin==='academia'?'Revisar bloque relacionado':'Volver al bloque'} →</a>${pageLinks?'<span>Consultar apuntes:</span>'+pageLinks:'<span>Clave procedente del test compartido.</span>'}</div>`}
document.querySelector('#quizlist').addEventListener('click',e=>{const button=e.target.closest('[data-answer]');if(!button)return;const i=Number(button.closest('[data-question]').dataset.question);if(Object.hasOwn(quizAnswers,i))return;quizAnswers[i]=Number(button.dataset.answer);displayAnswer(i,quizAnswers[i]);updateScore()});document.querySelector('#quiztopic').onchange=renderQuiz;document.querySelector('#quizsource').onchange=renderQuiz;document.querySelector('#resetquiz').onclick=()=>{quizPool().forEach(({i})=>delete quizAnswers[i]);renderQuiz()};renderQuiz();
if(location.hash==='#quiz')showView('quiz',false);
